use std::fs;

use axum::body::Body;
use axum::http::{Request, StatusCode, header};
use hoglet::application::{Application, ApplicationConfig, ApplicationError};
use hoglet::storage_bootstrap::{
    StorageDisposition, StoragePaths, bootstrap_storage, inspect_storage,
};
use http_body_util::BodyExt;
use serde_json::json;
use tower::ServiceExt;

#[tokio::test]
async fn fresh_storage_bootstraps_a_safe_production_router() {
    let directory = tempfile::tempdir().expect("temporary data directory");
    let config = ApplicationConfig::new(directory.path());

    let application = Application::prepare(config)
        .await
        .expect("fresh application starts");
    assert!(matches!(
        inspect_storage(&StoragePaths::new(directory.path())).expect("storage inspection"),
        StorageDisposition::ReadyV2(_)
    ));

    let router = application.router();
    assert_eq!(
        router
            .clone()
            .oneshot(Request::get("/health").body(Body::empty()).unwrap())
            .await
            .unwrap()
            .status(),
        StatusCode::OK
    );
    assert_eq!(
        router
            .clone()
            .oneshot(
                Request::get("/api/stats?token=phc_should_not_be_accepted")
                    .body(Body::empty())
                    .unwrap()
            )
            .await
            .unwrap()
            .status(),
        StatusCode::NOT_FOUND,
        "the legacy raw-token dashboard interface is not mounted"
    );
    assert_eq!(
        router
            .clone()
            .oneshot(
                Request::get("/api/admin/projects")
                    .body(Body::empty())
                    .unwrap()
            )
            .await
            .unwrap()
            .status(),
        StatusCode::NOT_FOUND,
        "the legacy admin interface is not mounted"
    );

    let wire_preflight = router
        .clone()
        .oneshot(
            Request::options("/e/")
                .header(header::ORIGIN, "https://sdk.example")
                .header(header::ACCESS_CONTROL_REQUEST_METHOD, "POST")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert!(
        wire_preflight
            .headers()
            .contains_key(header::ACCESS_CONTROL_ALLOW_ORIGIN),
        "wire capture is cross-origin by contract"
    );

    let dashboard_preflight = router
        .oneshot(
            Request::options("/api/workspace")
                .header(header::ORIGIN, "https://untrusted.example")
                .header(header::ACCESS_CONTROL_REQUEST_METHOD, "GET")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert!(
        !dashboard_preflight
            .headers()
            .contains_key(header::ACCESS_CONTROL_ALLOW_ORIGIN),
        "dashboard and control routes do not inherit wire CORS"
    );

    application.shutdown().await.expect("clean shutdown");
}

#[tokio::test]
async fn incomplete_storage_is_rejected_without_recovery_writes() {
    let directory = tempfile::tempdir().expect("temporary data directory");
    let partial = directory.path().join("control.db.migrating");
    fs::write(&partial, b"partial migration").expect("partial fixture");

    let error = Application::prepare(ApplicationConfig::new(directory.path()))
        .await
        .expect_err("incomplete migration cannot be guessed at startup");

    assert!(matches!(
        error,
        ApplicationError::MigrationIncomplete { .. }
    ));
    assert_eq!(
        fs::read(&partial).expect("partial fixture remains"),
        b"partial migration"
    );
    assert!(!directory.path().join("control.db").exists());
    assert!(!directory.path().join("projections.db").exists());
}

#[tokio::test]
async fn exact_fresh_pair_publish_crash_is_recovered_after_validation() {
    let directory = tempfile::tempdir().expect("temporary data directory");
    let paths = StoragePaths::new(directory.path());
    let expected = bootstrap_storage(paths.control(), paths.projections())
        .expect("fresh pair should bootstrap");
    fs::rename(paths.control(), paths.control_migrating())
        .expect("simulate crash after projections rename");

    let application = Application::prepare(ApplicationConfig::new(directory.path()))
        .await
        .expect("the exact fresh bootstrap crash state should recover");
    let recovered = match inspect_storage(&paths).expect("recovered pair should inspect") {
        StorageDisposition::ReadyV2(metadata) => metadata,
        disposition => panic!("expected ready storage, got {disposition:?}"),
    };
    assert_eq!(recovered.pair_id, expected.pair_id);
    assert!(!paths.control_migrating().exists());
    application.shutdown().await.expect("clean shutdown");
}

#[tokio::test]
async fn authorized_capture_reaches_a_leased_generation_query() {
    let directory = tempfile::tempdir().expect("temporary data directory");
    let application = Application::prepare(ApplicationConfig::new(directory.path()))
        .await
        .expect("application starts");
    let router = application.router();
    let setup = router
        .clone()
        .oneshot(
            Request::post("/api/auth/setup")
                .header(header::CONTENT_TYPE, "application/json")
                .body(Body::from(
                    json!({
                        "email": "owner@example.com",
                        "password": "correct horse battery staple",
                        "organization_name": "Acme",
                        "project_name": "Website",
                        "existing_project_token": "phc_application_e2e"
                    })
                    .to_string(),
                ))
                .unwrap(),
        )
        .await
        .expect("setup response");
    assert_eq!(setup.status(), StatusCode::OK);
    let cookie = setup
        .headers()
        .get(header::SET_COOKIE)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.split(';').next())
        .expect("session cookie")
        .to_owned();
    let setup_body: serde_json::Value = serde_json::from_slice(
        &setup
            .into_body()
            .collect()
            .await
            .expect("setup body")
            .to_bytes(),
    )
    .expect("workspace JSON");
    let project_id = setup_body["organizations"][0]["projects"][0]["id"]
        .as_str()
        .expect("project id")
        .to_owned();

    let capture = router
        .clone()
        .oneshot(
            Request::post("/e/")
                .header(header::CONTENT_TYPE, "application/json")
                .body(Body::from(
                    json!({
                        "event": "signed_up",
                        "distinct_id": "person-1",
                        "token": "phc_application_e2e",
                        "timestamp": "2026-08-20T12:00:00Z",
                        "properties": {"plan": "pro"}
                    })
                    .to_string(),
                ))
                .unwrap(),
        )
        .await
        .expect("capture response");
    assert_eq!(capture.status(), StatusCode::OK);

    let query_body = json!({
        "query": {
            "kind": "TrendsQuery",
            "series": [{"event": "signed_up", "math": "total"}],
            "date_range": {"date_from": "2026-08-20", "date_to": "2026-08-20"},
            "interval": "day"
        },
        "refresh": true
    });
    let mut observed = None;
    for _ in 0..100 {
        tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        let response = router
            .clone()
            .oneshot(
                Request::post(format!("/api/projects/{project_id}/query"))
                    .header(header::CONTENT_TYPE, "application/json")
                    .header(header::COOKIE, &cookie)
                    .body(Body::from(query_body.to_string()))
                    .unwrap(),
            )
            .await
            .expect("query response");
        assert_eq!(response.status(), StatusCode::OK);
        let body: serde_json::Value = serde_json::from_slice(
            &response
                .into_body()
                .collect()
                .await
                .expect("query body")
                .to_bytes(),
        )
        .expect("query JSON");
        if body["result"]["series"][0]["aggregated_value"] == 1.0 {
            observed = Some(body);
            break;
        }
    }
    let observed = observed.expect("publisher makes the durable receipt queryable");
    assert_eq!(observed["meta"]["data_version"], 1);

    let catalog = router
        .clone()
        .oneshot(
            Request::get(format!(
                "/api/projects/{project_id}/catalog/events?prefix=signed&limit=20"
            ))
            .header(header::COOKIE, &cookie)
            .body(Body::empty())
            .unwrap(),
        )
        .await
        .expect("catalog response");
    assert_eq!(catalog.status(), StatusCode::OK);
    let names: Vec<hoglet::contract::persons::CatalogEvent> = serde_json::from_slice(
        &catalog
            .into_body()
            .collect()
            .await
            .expect("catalog body")
            .to_bytes(),
    )
    .expect("catalog JSON");
    let names: Vec<&str> = names.iter().map(|event| event.name.as_str()).collect();
    assert_eq!(names, vec!["signed_up"]);

    let values = router
        .clone()
        .oneshot(
            Request::get(format!(
                "/api/projects/{project_id}/catalog/values?key=plan&limit=20"
            ))
            .header(header::COOKIE, &cookie)
            .body(Body::empty())
            .unwrap(),
        )
        .await
        .expect("catalog values response");
    assert_eq!(values.status(), StatusCode::OK);
    let values: Vec<hoglet::contract::persons::CatalogValue> = serde_json::from_slice(
        &values
            .into_body()
            .collect()
            .await
            .expect("catalog values body")
            .to_bytes(),
    )
    .expect("catalog values JSON");
    let values: Vec<&str> = values.iter().map(|value| value.value.as_str()).collect();
    assert_eq!(values, vec!["pro"]);

    drop(router);
    application.shutdown().await.expect("clean shutdown");
}

//! Strict bootstrap and pair validation for Hoglet's control and projection databases.
//!
//! This module deliberately owns only database identity and the initial projection
//! generation. Operational control tables are initialized by `control`; keeping
//! that boundary avoids a second, subtly different control schema.

use std::error::Error;
use std::fmt;
use std::fs;
use std::path::{Path, PathBuf};

use rusqlite::{Connection, OpenFlags, OptionalExtension};

/// SQLite application id for a Hoglet control database (`HCTL`).
pub const CONTROL_APPLICATION_ID: i64 = 0x4843_544c;
/// SQLite application id for a Hoglet projections database (`HPRJ`).
pub const PROJECTIONS_APPLICATION_ID: i64 = 0x4850_524a;
pub const CONTROL_SCHEMA_VERSION: i64 = 1;
/// 2: generation-tracked lake files, identity override sequencing.
pub const PROJECTIONS_SCHEMA_VERSION: i64 = 2;

const DATABASE_META_SCHEMA: &str = "
CREATE TABLE database_meta (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    pair_id TEXT NOT NULL CHECK (length(pair_id) > 0),
    database_role TEXT NOT NULL CHECK (database_role IN ('control', 'projections'))
);";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DatabaseRole {
    Control,
    Projections,
}

impl DatabaseRole {
    fn as_str(self) -> &'static str {
        match self {
            Self::Control => "control",
            Self::Projections => "projections",
        }
    }

    fn application_id(self) -> i64 {
        match self {
            Self::Control => CONTROL_APPLICATION_ID,
            Self::Projections => PROJECTIONS_APPLICATION_ID,
        }
    }

    fn schema_version(self) -> i64 {
        match self {
            Self::Control => CONTROL_SCHEMA_VERSION,
            Self::Projections => PROJECTIONS_SCHEMA_VERSION,
        }
    }
}

impl fmt::Display for DatabaseRole {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(self.as_str())
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StorageMetadata {
    pub pair_id: String,
    pub current_generation_id: i64,
    pub data_epoch: i64,
}

/// Canonical storage locations derived from one Hoglet data directory.
///
/// Keeping path derivation here prevents callers from accidentally inspecting
/// one installation and opening databases from another.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StoragePaths {
    data_dir: PathBuf,
}

impl StoragePaths {
    pub fn new(data_dir: impl AsRef<Path>) -> Self {
        Self {
            data_dir: data_dir.as_ref().to_path_buf(),
        }
    }

    pub fn data_dir(&self) -> &Path {
        &self.data_dir
    }

    pub fn control(&self) -> PathBuf {
        self.data_dir.join("control.db")
    }

    pub fn projections(&self) -> PathBuf {
        self.data_dir.join("projections.db")
    }

    /// Staging path used by the offline migration. It is intentionally
    /// visible to storage owners, but never opened by normal startup.
    pub fn control_migrating(&self) -> PathBuf {
        migrating_path(&self.control())
    }

    /// Staging path used by the offline migration. Projections are published
    /// before control so a crash cannot expose a control database without its
    /// rebuildable companion.
    pub fn projections_migrating(&self) -> PathBuf {
        migrating_path(&self.projections())
    }

}

/// Read-only startup classification for one data directory.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum StorageDisposition {
    /// No databases exist yet.
    Fresh,
    /// A complete, internally consistent database pair exists.
    ReadyV2(StorageMetadata),
    /// The pair or its crash-safe staging files are only partly present.
    MigrationIncomplete,
}

#[derive(Debug)]
pub enum StorageBootstrapError {
    IdenticalPaths,
    IncompletePair {
        present: DatabaseRole,
    },
    SchemaTooNew {
        role: DatabaseRole,
        found: i64,
        supported: i64,
    },
    SchemaTooOld {
        role: DatabaseRole,
        found: i64,
        supported: i64,
    },
    ApplicationIdMismatch {
        role: DatabaseRole,
        found: i64,
        expected: i64,
    },
    RoleMismatch {
        expected: DatabaseRole,
        found: String,
    },
    PairIdMismatch {
        control: String,
        projections: String,
    },
    InvalidMetadata {
        role: DatabaseRole,
        detail: &'static str,
    },
    Io {
        path: PathBuf,
        source: std::io::Error,
    },
    Sqlite {
        path: PathBuf,
        source: rusqlite::Error,
    },
}

impl fmt::Display for StorageBootstrapError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::IdenticalPaths => {
                formatter.write_str("control and projections paths are identical")
            }
            Self::IncompletePair { present } => {
                write!(
                    formatter,
                    "incomplete storage pair: only {present} database exists"
                )
            }
            Self::SchemaTooNew {
                role,
                found,
                supported,
            } => write!(
                formatter,
                "{role} database schema {found} is newer than supported schema {supported}"
            ),
            Self::SchemaTooOld {
                role,
                found,
                supported,
            } => write!(
                formatter,
                "{role} database schema {found} requires migration to schema {supported}"
            ),
            Self::ApplicationIdMismatch {
                role,
                found,
                expected,
            } => write!(
                formatter,
                "{role} database application id {found:#x} does not match {expected:#x}"
            ),
            Self::RoleMismatch { expected, found } => {
                write!(
                    formatter,
                    "expected {expected} database metadata, found role {found:?}"
                )
            }
            Self::PairIdMismatch {
                control,
                projections,
            } => write!(
                formatter,
                "control/projections pair ids differ ({control:?} != {projections:?})"
            ),
            Self::InvalidMetadata { role, detail } => {
                write!(formatter, "invalid {role} database metadata: {detail}")
            }
            Self::Io { path, source } => write!(formatter, "{}: {source}", path.display()),
            Self::Sqlite { path, source } => write!(formatter, "{}: {source}", path.display()),
        }
    }
}

impl Error for StorageBootstrapError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Io { source, .. } => Some(source),
            Self::Sqlite { source, .. } => Some(source),
            _ => None,
        }
    }
}

/// Classify a data directory without creating or mutating anything.
///
/// This is the safe first startup operation. In particular it does not create
/// `data_dir`, recover staging files, change SQLite journal modes, or install
/// runtime pragmas. A complete pair is opened with SQLite's read-only flag and
/// fully validated before it is reported as ready.
pub fn inspect_storage(paths: &StoragePaths) -> Result<StorageDisposition, StorageBootstrapError> {
    let control_path = paths.control();
    let projections_path = paths.projections();

    if paths.control_migrating().exists() || paths.projections_migrating().exists() {
        return Ok(StorageDisposition::MigrationIncomplete);
    }

    match (control_path.exists(), projections_path.exists()) {
        (true, true) => validate_pair_read_only(&control_path, &projections_path)
            .map(StorageDisposition::ReadyV2),
        (true, false) | (false, true) => Ok(StorageDisposition::MigrationIncomplete),
        (false, false) => Ok(StorageDisposition::Fresh),
    }
}

/// Validate a database pair without changing either database or its journal
/// mode. Offline migration uses this immediately before and after publication.
pub fn validate_storage_pair(
    control_path: impl AsRef<Path>,
    projections_path: impl AsRef<Path>,
) -> Result<StorageMetadata, StorageBootstrapError> {
    let control_path = control_path.as_ref();
    let projections_path = projections_path.as_ref();
    if control_path == projections_path {
        return Err(StorageBootstrapError::IdenticalPaths);
    }
    validate_pair_read_only(control_path, projections_path)
}

/// Create a fresh pair, validate an existing pair, or finish the one supported
/// crash-recovery state (published projections plus a validated staged control
/// database).
///
/// Callers that own a data directory should run [`inspect_storage`] first and
/// invoke this only for `Fresh` or `ReadyV2`. This compatibility API does not
/// classify legacy artifacts before creating a pair. Arbitrary incomplete pairs
/// are rejected; the staged-control recovery is accepted only after strict pair
/// validation.
pub fn bootstrap_storage(
    control_path: impl AsRef<Path>,
    projections_path: impl AsRef<Path>,
) -> Result<StorageMetadata, StorageBootstrapError> {
    let control_path = control_path.as_ref();
    let projections_path = projections_path.as_ref();
    if control_path == projections_path {
        return Err(StorageBootstrapError::IdenticalPaths);
    }
    let control_migrating = migrating_path(control_path);
    let projections_migrating = migrating_path(projections_path);

    match (control_path.exists(), projections_path.exists()) {
        (true, false) => {
            return Err(StorageBootstrapError::IncompletePair {
                present: DatabaseRole::Control,
            });
        }
        (false, true) if control_migrating.exists() => {
            validate_pair_read_only(&control_migrating, projections_path)?;
            fs::rename(&control_migrating, control_path).map_err(|source| {
                StorageBootstrapError::Io {
                    path: control_path.to_path_buf(),
                    source,
                }
            })?;
            sync_parent(control_path)?;
        }
        (false, true) => {
            return Err(StorageBootstrapError::IncompletePair {
                present: DatabaseRole::Projections,
            });
        }
        (false, false) => {
            remove_generated_temporary(&control_migrating)?;
            remove_generated_temporary(&projections_migrating)?;
            create_pair(control_path, projections_path)?;
        }
        (true, true) => {}
    }

    let metadata = validate_pair_read_only(control_path, projections_path)?;
    install_runtime_pragmas(control_path, projections_path)?;
    Ok(metadata)
}

fn create_pair(control_path: &Path, projections_path: &Path) -> Result<(), StorageBootstrapError> {
    ensure_parent(control_path)?;
    ensure_parent(projections_path)?;

    let control_migrating = migrating_path(control_path);
    let projections_migrating = migrating_path(projections_path);
    let pair_id = uuid::Uuid::new_v4().to_string();
    create_control_database(&control_migrating, &pair_id)?;
    create_projections_database(&projections_migrating, &pair_id)?;
    harden_file_permissions(&control_migrating)?;
    harden_file_permissions(&projections_migrating)?;
    sync_file(&control_migrating)?;
    sync_file(&projections_migrating)?;
    fs::rename(&projections_migrating, projections_path).map_err(|source| {
        StorageBootstrapError::Io {
            path: projections_path.to_path_buf(),
            source,
        }
    })?;
    sync_parent(projections_path)?;
    fs::rename(&control_migrating, control_path).map_err(|source| StorageBootstrapError::Io {
        path: control_path.to_path_buf(),
        source,
    })?;
    sync_parent(control_path)?;
    Ok(())
}

fn migrating_path(path: &Path) -> PathBuf {
    let mut name = path.as_os_str().to_owned();
    name.push(".migrating");
    PathBuf::from(name)
}

fn remove_generated_temporary(path: &Path) -> Result<(), StorageBootstrapError> {
    if path.exists() {
        fs::remove_file(path).map_err(|source| StorageBootstrapError::Io {
            path: path.to_path_buf(),
            source,
        })?;
    }
    Ok(())
}

fn sync_file(path: &Path) -> Result<(), StorageBootstrapError> {
    fs::File::open(path)
        .and_then(|file| file.sync_all())
        .map_err(|source| StorageBootstrapError::Io {
            path: path.to_path_buf(),
            source,
        })
}

fn sync_parent(path: &Path) -> Result<(), StorageBootstrapError> {
    let parent = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty());
    if let Some(parent) = parent {
        fs::File::open(parent)
            .and_then(|directory| directory.sync_all())
            .map_err(|source| StorageBootstrapError::Io {
                path: parent.to_path_buf(),
                source,
            })?;
    }
    Ok(())
}

fn ensure_parent(path: &Path) -> Result<(), StorageBootstrapError> {
    let Some(parent) = path.parent() else {
        return Ok(());
    };
    if parent.as_os_str().is_empty() {
        return Ok(());
    }
    let existed = parent.exists();
    fs::create_dir_all(parent).map_err(|source| StorageBootstrapError::Io {
        path: parent.to_path_buf(),
        source,
    })?;
    if !existed {
        harden_directory_permissions(parent)?;
    }
    Ok(())
}

#[cfg(unix)]
fn harden_file_permissions(path: &Path) -> Result<(), StorageBootstrapError> {
    use std::os::unix::fs::PermissionsExt;
    fs::set_permissions(path, fs::Permissions::from_mode(0o600)).map_err(|source| {
        StorageBootstrapError::Io {
            path: path.to_path_buf(),
            source,
        }
    })
}

#[cfg(not(unix))]
fn harden_file_permissions(_path: &Path) -> Result<(), StorageBootstrapError> {
    Ok(())
}

#[cfg(unix)]
fn harden_directory_permissions(path: &Path) -> Result<(), StorageBootstrapError> {
    use std::os::unix::fs::PermissionsExt;
    fs::set_permissions(path, fs::Permissions::from_mode(0o700)).map_err(|source| {
        StorageBootstrapError::Io {
            path: path.to_path_buf(),
            source,
        }
    })
}

#[cfg(not(unix))]
fn harden_directory_permissions(_path: &Path) -> Result<(), StorageBootstrapError> {
    Ok(())
}

fn create_control_database(path: &Path, pair_id: &str) -> Result<(), StorageBootstrapError> {
    let mut connection = open_database(path)?;
    initialize_pragmas(&connection, DatabaseRole::Control)?;
    let transaction = connection
        .transaction()
        .map_err(|source| sqlite_error(path, source))?;
    transaction
        .execute_batch(DATABASE_META_SCHEMA)
        .map_err(|source| sqlite_error(path, source))?;
    transaction
        .execute(
            "INSERT INTO database_meta (singleton, pair_id, database_role) VALUES (1, ?1, 'control')",
            [pair_id],
        )
        .map_err(|source| sqlite_error(path, source))?;
    transaction
        .commit()
        .map_err(|source| sqlite_error(path, source))
}

fn create_projections_database(path: &Path, pair_id: &str) -> Result<(), StorageBootstrapError> {
    let mut connection = open_database(path)?;
    initialize_pragmas(&connection, DatabaseRole::Projections)?;
    let transaction = connection
        .transaction()
        .map_err(|source| sqlite_error(path, source))?;
    transaction
        .execute_batch(DATABASE_META_SCHEMA)
        .and_then(|_| transaction.execute_batch(crate::lake::SCHEMA))
        .map_err(|source| sqlite_error(path, source))?;
    crate::projections::initialize_schema(&transaction).map_err(|_| {
        StorageBootstrapError::InvalidMetadata {
            role: DatabaseRole::Projections,
            detail: "projection schema could not be installed",
        }
    })?;
    transaction
        .execute(
            "INSERT INTO database_meta (singleton, pair_id, database_role)
             VALUES (1, ?1, 'projections')",
            [pair_id],
        )
        .map_err(|source| sqlite_error(path, source))?;
    transaction
        .commit()
        .map_err(|source| sqlite_error(path, source))
}

fn initialize_pragmas(
    connection: &Connection,
    role: DatabaseRole,
) -> Result<(), StorageBootstrapError> {
    let path = PathBuf::from(connection.path().unwrap_or("<sqlite>"));
    connection
        .execute_batch(
            "PRAGMA foreign_keys=ON; PRAGMA journal_mode=DELETE; PRAGMA synchronous=FULL;",
        )
        .map_err(|source| StorageBootstrapError::Sqlite {
            path: path.clone(),
            source,
        })?;
    connection
        .pragma_update(None, "application_id", role.application_id())
        .and_then(|_| connection.pragma_update(None, "user_version", role.schema_version()))
        .map_err(|source| StorageBootstrapError::Sqlite { path, source })
}

fn validate_pair_read_only(
    control_path: &Path,
    projections_path: &Path,
) -> Result<StorageMetadata, StorageBootstrapError> {
    let control = open_database_read_only(control_path)?;
    let projections = open_database_read_only(projections_path)?;

    validate_header(&control, control_path, DatabaseRole::Control)?;
    validate_header(&projections, projections_path, DatabaseRole::Projections)?;

    let control_pair = read_pair_id(&control, control_path, DatabaseRole::Control)?;
    let projections_pair = read_pair_id(&projections, projections_path, DatabaseRole::Projections)?;
    if control_pair != projections_pair {
        return Err(StorageBootstrapError::PairIdMismatch {
            control: control_pair,
            projections: projections_pair,
        });
    }

    let generation: i64 = projections
        .query_row(
            "SELECT generation FROM projection_state WHERE singleton = 1",
            [],
            |row| row.get(0),
        )
        .optional()
        .map_err(|source| sqlite_error(projections_path, source))?
        .ok_or(StorageBootstrapError::InvalidMetadata {
            role: DatabaseRole::Projections,
            detail: "projection state is absent",
        })?;

    Ok(StorageMetadata {
        pair_id: control_pair,
        current_generation_id: generation,
        data_epoch: 0,
    })
}

fn install_runtime_pragmas(
    control_path: &Path,
    projections_path: &Path,
) -> Result<(), StorageBootstrapError> {
    let control = open_database(control_path)?;
    let projections = open_database(projections_path)?;
    set_runtime_pragmas(&control, control_path)?;
    set_runtime_pragmas(&projections, projections_path)
}

fn validate_header(
    connection: &Connection,
    path: &Path,
    role: DatabaseRole,
) -> Result<(), StorageBootstrapError> {
    let version: i64 = connection
        .pragma_query_value(None, "user_version", |row| row.get(0))
        .map_err(|source| sqlite_error(path, source))?;
    let supported = role.schema_version();
    if version > supported {
        return Err(StorageBootstrapError::SchemaTooNew {
            role,
            found: version,
            supported,
        });
    }
    if version < supported {
        return Err(StorageBootstrapError::SchemaTooOld {
            role,
            found: version,
            supported,
        });
    }

    let application_id: i64 = connection
        .pragma_query_value(None, "application_id", |row| row.get(0))
        .map_err(|source| sqlite_error(path, source))?;
    let expected = role.application_id();
    if application_id != expected {
        return Err(StorageBootstrapError::ApplicationIdMismatch {
            role,
            found: application_id,
            expected,
        });
    }
    Ok(())
}

fn set_runtime_pragmas(connection: &Connection, path: &Path) -> Result<(), StorageBootstrapError> {
    connection
        .execute_batch("PRAGMA foreign_keys=ON; PRAGMA journal_mode=WAL; PRAGMA synchronous=FULL;")
        .map_err(|source| sqlite_error(path, source))
}

fn read_pair_id(
    connection: &Connection,
    path: &Path,
    role: DatabaseRole,
) -> Result<String, StorageBootstrapError> {
    let metadata = connection
        .query_row(
            "SELECT pair_id, database_role FROM database_meta WHERE singleton = 1",
            [],
            |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
        )
        .optional()
        .map_err(|source| sqlite_error(path, source))?
        .ok_or(StorageBootstrapError::InvalidMetadata {
            role,
            detail: "database_meta singleton is absent",
        })?;
    if metadata.0.is_empty() {
        return Err(StorageBootstrapError::InvalidMetadata {
            role,
            detail: "pair id is empty",
        });
    }
    if metadata.1 != role.as_str() {
        return Err(StorageBootstrapError::RoleMismatch {
            expected: role,
            found: metadata.1,
        });
    }
    Ok(metadata.0)
}

fn open_database(path: &Path) -> Result<Connection, StorageBootstrapError> {
    Connection::open(path).map_err(|source| sqlite_error(path, source))
}

fn open_database_read_only(path: &Path) -> Result<Connection, StorageBootstrapError> {
    // `READ_ONLY` alone may still create `-wal`/`-shm` files when the database
    // header records WAL mode. SQLite's immutable URI mode forbids all writes,
    // which is the contract startup inspection and offline validation require.
    let uri = format!("file:{}?immutable=1", sqlite_uri_path(path));
    Connection::open_with_flags(
        uri,
        OpenFlags::SQLITE_OPEN_READ_ONLY
            | OpenFlags::SQLITE_OPEN_NO_MUTEX
            | OpenFlags::SQLITE_OPEN_URI,
    )
    .map_err(|source| sqlite_error(path, source))
}

fn sqlite_uri_path(path: &Path) -> String {
    let text = path.to_string_lossy();
    let mut encoded = String::with_capacity(text.len());
    for byte in text.bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'/' | b':' | b'-' | b'.' | b'_' | b'~') {
            encoded.push(char::from(byte));
        } else {
            use std::fmt::Write as _;
            let _ = write!(encoded, "%{byte:02X}");
        }
    }
    encoded
}

fn sqlite_error(path: &Path, source: rusqlite::Error) -> StorageBootstrapError {
    StorageBootstrapError::Sqlite {
        path: path.to_path_buf(),
        source,
    }
}

//! No-panic and bounded-cost properties for everything an anonymous client
//! controls: the capture decoder and parser, the capture and flags endpoints,
//! and flag regexes.

use axum::{
    Router,
    body::Body,
    http::{Method, Request, StatusCode, header},
};
use hoglet::application::{Application, ApplicationConfig};
use hoglet::capture::{decompress, event};
use http_body_util::BodyExt;
use proptest::prelude::*;
use serde_json::{Value, json};
use tower::ServiceExt;

proptest! {
    #![proptest_config(ProptestConfig { cases: 8000, ..ProptestConfig::default() })]

    #[test]
    fn decode_never_panics(
        body in proptest::collection::vec(any::<u8>(), 0..512),
        form in any::<bool>(),
        hint in proptest::option::of(prop_oneof![Just("lz64"), Just("gzip"), Just("gzip-js"), Just("base64"), Just("x")]),
    ) {
        let _ = decompress::decode_limited(&body, form, hint, 1 << 20);
    }

    #[test]
    fn decode_never_panics_on_structured_inputs(
        text in "[A-Za-z0-9+/=%&_.\\- ]{0,400}",
        prefix in prop_oneof![Just(""), Just("data="), Just("data=H4sI"), Just("compression=lz64&data=")],
        form in any::<bool>(),
        hint in proptest::option::of(prop_oneof![Just("lz64"), Just("gzip")]),
    ) {
        let body = format!("{prefix}{text}");
        let _ = decompress::decode_limited(body.as_bytes(), form, hint, 1 << 20);
    }

    #[test]
    fn timestamps_never_panic(raw in "\\PC{0,40}", suffix in "[+-]?[0-9a-z]{0,3}") {
        let _ = event::parse_timestamp(&raw);
        let _ = event::parse_timestamp(&format!("{raw}{suffix}"));
    }

    #[test]
    fn parse_body_never_panics_on_arbitrary_text(text in ".{0,600}") {
        let now = chrono::Utc::now();
        let _ = event::parse_body(&text, None, now);
    }

    #[test]
    fn parse_body_never_panics_on_event_shaped_json(value in event_like()) {
        let now = chrono::Utc::now();
        let _ = event::parse_body(&value.to_string(), event::parse_sent_at_ms("1700000000000"), now);
    }
}

/// Event-shaped JSON with hostile field types and values.
fn event_like() -> impl Strategy<Value = Value> {
    let leaf = prop_oneof![
        Just(Value::Null),
        any::<bool>().prop_map(Value::Bool),
        any::<i64>().prop_map(|number| json!(number)),
        any::<f64>().prop_map(|number| json!(number)),
        ".{0,40}".prop_map(Value::String),
        Just(json!("2026-10-05T00:00:00Z")),
        Just(json!("not a time")),
        Just(json!("00000000-0000-0000-0000-000000000000")),
    ];
    let field = prop_oneof![
        Just("event"), Just("distinct_id"), Just("$distinct_id"), Just("token"),
        Just("$token"), Just("api_key"), Just("timestamp"), Just("offset"),
        Just("uuid"), Just("properties"), Just("$set"), Just("$set_once"),
        Just("batch"), Just("sent_at"), Just("historical_migration"),
        Just("$ignore_sent_at"),
    ];
    leaf.prop_recursive(3, 24, 4, move |inner| {
        prop_oneof![
            proptest::collection::vec(inner.clone(), 0..4).prop_map(Value::Array),
            proptest::collection::vec((field.clone(), inner), 0..6)
                .prop_map(|pairs| Value::Object(pairs.into_iter().map(|(k, v)| (k.to_owned(), v)).collect())),
        ]
    })
}

async fn send(router: &Router, request: Request<Body>) -> StatusCode {
    let response = router.clone().oneshot(request).await.unwrap();
    let status = response.status();
    let _ = response.into_body().collect().await.unwrap();
    status
}

struct Server {
    runtime: tokio::runtime::Runtime,
    application: Application,
    router: Router,
    cookie: String,
    project_id: String,
    _dir: tempfile::TempDir,
}

fn server() -> Server {
    let runtime = tokio::runtime::Builder::new_multi_thread().enable_all().build().unwrap();
    let dir = tempfile::tempdir().unwrap();
    let (application, router, cookie, project_id) = runtime.block_on(async {
        let application = Application::prepare(ApplicationConfig::new(dir.path())).await.unwrap();
        let router = application.router();
        let response = router
            .clone()
            .oneshot(
                Request::post("/api/auth/setup")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        json!({"email": "o@example.com", "password": "correct horse battery", "organization_name": "O", "existing_project_token": "phc_fuzz"})
                            .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        let cookie = response
            .headers()
            .get(header::SET_COOKIE)
            .unwrap()
            .to_str()
            .unwrap()
            .split(';')
            .next()
            .unwrap()
            .to_owned();
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let workspace: Value = serde_json::from_slice(&body).unwrap();
        let project_id = workspace["organizations"][0]["projects"][0]["id"].as_str().unwrap().to_owned();
        (application, router, cookie, project_id)
    });
    Server { runtime, application, router, cookie, project_id, _dir: dir }
}

#[test]
fn wire_endpoints_never_5xx_or_panic_on_garbage() {
    let server = server();
    let mut runner = proptest::test_runner::TestRunner::new(ProptestConfig { cases: 600, ..ProptestConfig::default() });
    let strategy = (
        prop_oneof![Just("/e/"), Just("/batch/"), Just("/i/v0/e/"), Just("/flags/?v=2"), Just("/decide/?v=3"), Just("/engage/"), Just("/array/phc_fuzz/config")],
        prop_oneof![
            proptest::collection::vec(any::<u8>(), 0..300).prop_map(|bytes| bytes),
            event_like().prop_map(|value| value.to_string().into_bytes()),
            event_like().prop_map(|value| {
                let mut wrapped = json!({"api_key": "phc_fuzz", "batch": [value]}).to_string().into_bytes();
                wrapped.truncate(4000);
                wrapped
            }),
        ],
        proptest::option::of(prop_oneof![Just("gzip-js"), Just("lz64"), Just("base64")]),
        any::<bool>(),
    );
    runner
        .run(&strategy, |(path, body, compression, form)| {
            let uri = match compression {
                Some(c) if path.contains('?') => format!("{path}&compression={c}"),
                Some(c) => format!("{path}?compression={c}"),
                None => path.to_owned(),
            };
            let mut request = Request::builder().method(if path.starts_with("/array") { Method::GET } else { Method::POST }).uri(uri);
            if form {
                request = request.header(header::CONTENT_TYPE, "application/x-www-form-urlencoded");
            }
            let status = server.runtime.block_on(send(&server.router, request.body(Body::from(body)).unwrap()));
            prop_assert!(
                status.as_u16() < 500 || status == StatusCode::SERVICE_UNAVAILABLE,
                "{path} answered {status}"
            );
            Ok(())
        })
        .unwrap();
    let Server { runtime, application, router, .. } = server;
    drop(router);
    runtime.block_on(application.shutdown()).unwrap();
}

#[test]
fn flag_regexes_are_bounded() {
    let server = server();
    let create = |pattern: String| {
        Request::post(format!("/api/projects/{}/feature_flags", server.project_id))
            .header(header::CONTENT_TYPE, "application/json")
            .header(header::COOKIE, &server.cookie)
            .body(Body::from(
                json!({
                    "key": "regex-flag",
                    "filters": {"groups": [{"properties": [{"key": "email", "type": "person", "operator": "regex", "value": pattern}], "rollout_percentage": 100}]}
                })
                .to_string(),
            ))
            .unwrap()
    };
    // A program far past the compiled-size budget is refused or inert, and
    // quickly; never an allocation spike or a hang.
    let started = std::time::Instant::now();
    for pattern in ["((((a{100}){100}){100}){100})", "(a+)+$", "(.*){1000}", "[\\w\\W]{1000}{1000}"] {
        let status = server.runtime.block_on(send(&server.router, create(pattern.to_owned())));
        assert!(status.as_u16() < 500, "{pattern} -> {status}");
        let status = server.runtime.block_on(send(
            &server.router,
            Request::post("/flags/?v=2")
                .body(Body::from(
                    json!({"token": "phc_fuzz", "distinct_id": "u", "person_properties": {"email": "a".repeat(5000) + "!"}})
                        .to_string(),
                ))
                .unwrap(),
        ));
        assert!(status.as_u16() < 500, "{pattern} evaluate -> {status}");
    }
    assert!(started.elapsed() < std::time::Duration::from_secs(5), "{:?}", started.elapsed());
    let Server { runtime, application, router, .. } = server;
    drop(router);
    runtime.block_on(application.shutdown()).unwrap();
}

/// Flags with every operator and hostile values, evaluated against hostile
/// person properties: never a 5xx, never a panic.
#[test]
fn flag_evaluation_never_panics_for_any_operator_or_value() {
    let server = server();
    let operators = [
        "exact", "is_not", "icontains", "not_icontains", "regex", "not_regex", "gt", "gte", "lt",
        "lte", "is_set", "is_not_set", "is_date_before", "is_date_after",
    ];
    let value = || {
        prop_oneof![
            Just(Value::Null),
            any::<bool>().prop_map(Value::Bool),
            any::<i64>().prop_map(|number| json!(number)),
            any::<f64>().prop_map(|number| json!(number)),
            "\\PC{0,24}".prop_map(Value::String),
            prop_oneof![
                Just("-99999999999999999999d"),
                Just("-9223372036854775808h"),
                Just("-10000d"),
                Just("-1y"),
                Just("2026-13-45"),
                Just("+262142-12-31T23:59:59Z"),
                Just("-262143-01-01T00:00:00Z"),
                Just("1e999"),
                Just("(a+)+$"),
            ]
            .prop_map(|text| Value::String(text.to_owned())),
            proptest::collection::vec(any::<i32>().prop_map(|number| json!(number)), 0..4)
                .prop_map(Value::Array),
        ]
    };
    let mut runner = proptest::test_runner::TestRunner::new(ProptestConfig {
        cases: 400,
        ..ProptestConfig::default()
    });
    let counter = std::cell::Cell::new(0_u32);
    runner
        .run(
            &(0..operators.len(), value(), value()),
            |(operator, filter_value, person_value)| {
                counter.set(counter.get() + 1);
                let key = format!("fuzz-flag-{}", counter.get());
                let create = Request::post(format!("/api/projects/{}/feature_flags", server.project_id))
                    .header(header::CONTENT_TYPE, "application/json")
                    .header(header::COOKIE, &server.cookie)
                    .body(Body::from(
                        json!({
                            "key": key,
                            "filters": {"groups": [{
                                "properties": [{"key": "p", "type": "person", "operator": operators[operator], "value": filter_value}],
                                "rollout_percentage": 100
                            }]}
                        })
                        .to_string(),
                    ))
                    .unwrap();
                let status = server.runtime.block_on(send(&server.router, create));
                prop_assert!(status.as_u16() < 500, "create {operator} -> {status}");
                let evaluate = Request::post("/flags/?v=2")
                    .body(Body::from(
                        json!({"token": "phc_fuzz", "distinct_id": "u", "person_properties": {"p": person_value}})
                            .to_string(),
                    ))
                    .unwrap();
                let status = server.runtime.block_on(send(&server.router, evaluate));
                prop_assert!(status == StatusCode::OK, "evaluate {operator} -> {status}");
                Ok(())
            },
        )
        .unwrap();
    let Server { runtime, application, router, .. } = server;
    drop(router);
    runtime.block_on(application.shutdown()).unwrap();
}

//! Security regression tests over the real composed application: CSRF,
//! cookies, login throttling, setup, response headers, metrics, SSRF policy,
//! capture amplification, share redaction, tenant isolation, file modes.

use axum::{
    Router,
    body::Body,
    http::{HeaderMap, Method, Request, StatusCode, header},
};
use hoglet::application::{Application, ApplicationConfig};
use http_body_util::BodyExt;
use serde_json::{Value, json};
use tower::ServiceExt;

const PASSWORD: &str = "correct horse battery staple";

struct Harness {
    application: Application,
    router: Router,
    dir: tempfile::TempDir,
    cookie: String,
    project_id: String,
    token: String,
}

async fn send(router: &Router, request: Request<Body>) -> (StatusCode, HeaderMap, Vec<u8>) {
    let response = router.clone().oneshot(request).await.unwrap();
    let status = response.status();
    let headers = response.headers().clone();
    let body = response.into_body().collect().await.unwrap().to_bytes().to_vec();
    (status, headers, body)
}

fn json_body(bytes: &[u8]) -> Value {
    serde_json::from_slice(bytes).unwrap_or(Value::Null)
}

fn post(uri: &str, cookie: Option<&str>) -> axum::http::request::Builder {
    let mut builder = Request::builder()
        .method(Method::POST)
        .uri(uri)
        .header(header::CONTENT_TYPE, "application/json");
    if let Some(cookie) = cookie {
        builder = builder.header(header::COOKIE, cookie);
    }
    builder
}

async fn start_with(tweak: impl FnOnce(&mut ApplicationConfig)) -> Harness {
    let dir = tempfile::tempdir().unwrap();
    let mut config = ApplicationConfig::new(dir.path());
    tweak(&mut config);
    let application = Application::prepare(config).await.unwrap();
    application.mark_ready();
    let router = application.router();
    let (status, headers, body) = send(
        &router,
        post("/api/auth/setup", None)
            .body(Body::from(
                json!({
                    "email": "owner@example.com",
                    "password": PASSWORD,
                    "organization_name": "Acme",
                    "project_name": "Site",
                    "existing_project_token": "phc_security_tests"
                })
                .to_string(),
            ))
            .unwrap(),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&body));
    let cookie = headers
        .get(header::SET_COOKIE)
        .unwrap()
        .to_str()
        .unwrap()
        .split(';')
        .next()
        .unwrap()
        .to_owned();
    let workspace = json_body(&body);
    Harness {
        application,
        router,
        dir,
        cookie,
        project_id: workspace["organizations"][0]["projects"][0]["id"]
            .as_str()
            .unwrap()
            .to_owned(),
        token: "phc_security_tests".to_owned(),
    }
}

async fn start() -> Harness {
    start_with(|_| {}).await
}

impl Harness {
    async fn finish(self) {
        drop(self.router);
        self.application.shutdown().await.unwrap();
        drop(self.dir);
    }

    fn insights_uri(&self) -> String {
        format!("/api/projects/{}/insights", self.project_id)
    }

    fn insight_body() -> Body {
        Body::from(
            json!({
                "name": "SQL",
                "query_ir": {"kind": "SqlQuery", "query": "select 1 as secret_text"}
            })
            .to_string(),
        )
    }
}

// --- CSRF -----------------------------------------------------------------

#[tokio::test]
async fn cookie_authenticated_mutations_refuse_cross_site_requests() {
    let h = start().await;
    let uri = h.insights_uri();
    let make = |extra: Option<(&str, &str)>, cookie: bool| {
        let mut builder = Request::builder()
            .method(Method::POST)
            .uri(&uri)
            .header(header::CONTENT_TYPE, "application/json")
            .header(header::HOST, "hoglet.example");
        if cookie {
            builder = builder.header(header::COOKIE, &h.cookie);
        }
        if let Some((name, value)) = extra {
            builder = builder.header(name, value);
        }
        builder.body(Body::from(
            json!({"name": "i", "query_ir": {"kind": "SqlQuery", "query": "select 1"}}).to_string(),
        ))
        .unwrap()
    };

    // A page on another site, or a sibling subdomain, cannot ride the cookie.
    for hostile in [
        ("origin", "https://evil.example"),
        ("origin", "null"),
        ("sec-fetch-site", "cross-site"),
        ("sec-fetch-site", "same-site"),
    ] {
        let (status, _, _) = send(&h.router, make(Some(hostile), true)).await;
        assert_eq!(status, StatusCode::FORBIDDEN, "{hostile:?}");
    }
    // The dashboard itself, and non-browser clients, are unaffected.
    for fine in [
        Some(("origin", "https://hoglet.example")),
        Some(("sec-fetch-site", "same-origin")),
        None,
    ] {
        let (status, _, body) = send(&h.router, make(fine, true)).await;
        assert_eq!(status, StatusCode::CREATED, "{fine:?}: {}", String::from_utf8_lossy(&body));
    }
    // A cross-site origin without the cookie is just an anonymous request.
    let (status, _, _) = send(&h.router, make(Some(("origin", "https://evil.example")), false)).await;
    assert_eq!(status, StatusCode::UNAUTHORIZED);
    // The wire edge keeps its permissive CORS: SDKs run on other origins.
    let (status, headers, _) = send(
        &h.router,
        Request::builder()
            .method(Method::POST)
            .uri("/e/")
            .header("origin", "https://customer.example")
            .body(Body::from(
                json!({"event": "x", "distinct_id": "u", "token": h.token}).to_string(),
            ))
            .unwrap(),
    )
    .await;
    assert_eq!(status, StatusCode::OK);
    assert!(headers.contains_key("access-control-allow-origin"));
    h.finish().await;
}

