        "http://[::1]:9000",
        "http://[::ffff:10.0.0.1]/",
        "http://10.0.0.5",
        "http://192.168.0.10:8080",
        "http://100.100.100.200",
        "http://user:pass@example.com",
        "ftp://example.com",
