    let paths: Vec<(Method, String, Value)> = vec![
        (Method::GET, format!("/api/projects/{other}/insights"), Value::Null),
        (Method::POST, format!("/api/projects/{other}/insights"), json!({"name": "x", "query_ir": {"kind": "SqlQuery", "query": "select 1"}})),
