    let today = chrono::Utc::now().format("%Y-%m-%d").to_string();
    let posthog_rows = json!({"results": [
        [today, "signed_up", 2, 2],
        [today, "$pageview", 3, 1]
    ]});
    let posthog = serve(Router::new().route(
        "/api/projects/1/query/",
        post(move || {
            let rows = posthog_rows.clone();
            async move { Json(rows) }
        }),
    ))
    .await;

    let data = tempfile::tempdir().unwrap();
    let application = Application::prepare(ApplicationConfig::new(data.path()))
        .await
        .unwrap();
    application.mark_ready();
    let hoglet = serve(application.router()).await;
    let (setup, cookie) = call(
        format!("{hoglet}/api/auth/setup"),
        json!({"email": "o@example.com", "password": "correct horse battery", "organization_name": "Org", "project_name": "Reconcile"}),
        None,
    );
    let project = &setup["organizations"][0]["projects"][0];
    let project_id = project["id"].as_str().unwrap().to_owned();
    let token = project["token"].as_str().unwrap().to_owned();
    let (key, _) = call(format!("{hoglet}/api/auth/keys"), json!({"name": "reconcile"}), cookie);
    let secret = key["secret"].as_str().unwrap().to_owned();

    // Hoglet sees one signed_up fewer than PostHog.
    call(
        format!("{hoglet}/batch/"),
        json!({"api_key": token, "batch": [
            {"event": "signed_up", "distinct_id": "a"},
            {"event": "$pageview", "distinct_id": "a"},
            {"event": "$pageview", "distinct_id": "a"},
            {"event": "$pageview", "distinct_id": "a"}
        ]}),
        None,
    );

    let config = ReconcileConfig {
        posthog_host: posthog,
        posthog_project_id: "1".into(),
        posthog_key: "phx_posthog".into(),
        hoglet_host: hoglet,
        hoglet_project_id: project_id,
        hoglet_key: secret,
        days: 7,
        tolerance_percent: 0.5,
    };
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(15);
    let rows = loop {
        let attempt = config.clone();
        let rows = tokio::task::spawn_blocking(move || run(&attempt)).await.unwrap().expect("reconcile runs");
        if rows.iter().any(|row| row.hoglet.events > 0) {
            break rows;
        }
        assert!(std::time::Instant::now() < deadline, "Hoglet never answered with data");
        tokio::time::sleep(std::time::Duration::from_millis(200)).await;
    };
    let pageview = rows.iter().find(|row| row.event == "$pageview").unwrap();
    assert_eq!((pageview.hoglet.events, pageview.hoglet.persons), (3, 1));
    assert_eq!(pageview.events_diff_percent(), 0.0);
    let signup = rows.iter().find(|row| row.event == "signed_up").unwrap();
    assert_eq!((signup.hoglet.events, signup.posthog.events), (1, 2));
    let (table, all_match) = render(&rows, 0.5);
    assert!(!all_match);
    assert!(table.contains("signed_up"));
    application.shutdown().await.unwrap();
}

//! Realistic event datasets, a lake + projection fixture, and brute-force
//! reference implementations of the explore metrics.
#![allow(dead_code)]

use std::collections::{BTreeMap, HashMap, HashSet};
use std::path::PathBuf;
use std::sync::Arc;

use chrono::{DateTime, Duration, NaiveDate, Utc};
use hoglet::capture::event::CapturedEvent;
use hoglet::explore::Explorer;
use hoglet::persons::PersonStore;
use hoglet::pipeline::wal::WalCursor;
use hoglet::source::DirectorySource;
use rand::rngs::StdRng;
use rand::{Rng, SeedableRng};
use rusqlite::Connection;
use serde_json::{Map, Value, json};
use uuid::Uuid;

pub const PATHS: &[&str] = &["/", "/pricing", "/docs", "/blog", "/signup", "/about"];
const BROWSERS: &[&str] = &["Chrome", "Firefox", "Safari"];
const OSES: &[&str] = &["Windows", "Mac OS X", "iOS", "Android"];
const DEVICES: &[&str] = &["Desktop", "Mobile"];
const COUNTRIES: &[&str] = &["US", "DE", "IN", "GB"];
const REFERRERS: &[&str] = &["google.com", "news.ycombinator.com", "twitter.com"];
const UTM_SOURCES: &[&str] = &["newsletter", "google", "twitter"];
const UTM_MEDIUMS: &[&str] = &["email", "cpc", "social"];
const UTM_CAMPAIGNS: &[&str] = &["launch", "spring", "retarget"];

pub struct Spec {
    pub seed: u64,
    pub humans: usize,
    pub start: DateTime<Utc>,
    pub days: i64,
    pub max_sessions_per_device: usize,
}

pub struct Dataset {
    /// Sorted by timestamp, timestamps strictly increasing.
    pub events: Vec<CapturedEvent>,
    /// Ground truth: distinct id -> the person it must resolve to.
    pub person_of: HashMap<String, String>,
}

fn pick<'a>(rng: &mut StdRng, items: &[&'a str]) -> &'a str {
    items[rng.gen_range(0..items.len())]
}

pub fn event(
    name: &str,
    distinct_id: &str,
    timestamp: DateTime<Utc>,
    properties: Value,
) -> CapturedEvent {
    let properties = match properties {
        Value::Object(map) => map,
        _ => Map::new(),
    };
    CapturedEvent {
        uuid: Uuid::new_v4(),
        event: name.to_owned(),
        distinct_id: distinct_id.to_owned(),
        token: "phc_test".to_owned(),
        timestamp,
        properties,
    }
}

pub fn generate(spec: &Spec) -> Dataset {
    let mut rng = StdRng::seed_from_u64(spec.seed);
    let mut events = Vec::new();
    let mut person_of = HashMap::new();
    let span_seconds = spec.days * 86_400;
    for human in 0..spec.humans {
        let identifies = rng.gen_bool(0.6);
        let user_id = format!("user-{human}");
        let devices = if identifies { rng.gen_range(1..=3) } else { 1 };
        let plan = if rng.gen_bool(0.5) { "free" } else { "pro" };
        for device in 0..devices {
            let anon = format!("anon-{human}-{device}");
            person_of.insert(
                anon.clone(),
                if identifies {
                    user_id.clone()
                } else {
                    anon.clone()
                },
            );
            let browser = pick(&mut rng, BROWSERS);
            let os = pick(&mut rng, OSES);
            let device_type = pick(&mut rng, DEVICES);
            let country = if rng.gen_bool(0.1) {
                None
            } else {
                Some(pick(&mut rng, COUNTRIES))
            };
            let sessions = rng.gen_range(1..=spec.max_sessions_per_device);
            let login_session = identifies.then(|| rng.gen_range(0..sessions));
            let mut starts: Vec<i64> = (0..sessions)
                .map(|_| rng.gen_range(0..span_seconds.max(1)))
                .collect();
            starts.sort_unstable();
            let mut current_id = anon.clone();
            for (index, start) in starts.into_iter().enumerate() {
                let mut at = spec.start + Duration::seconds(start);
                let session_id = rng.gen_bool(0.85).then(|| Uuid::new_v4().to_string());
                let pageviews = if rng.gen_bool(0.4) {
                    1
                } else {
                    rng.gen_range(2..=5)
                };
                let direct = rng.gen_bool(0.3);
                let referrer = pick(&mut rng, REFERRERS);
                let tagged = rng.gen_bool(0.5);
                let utm = (
                    pick(&mut rng, UTM_SOURCES),
                    pick(&mut rng, UTM_MEDIUMS),
                    pick(&mut rng, UTM_CAMPAIGNS),
                );
                for view in 0..pageviews {
                    let path = pick(&mut rng, PATHS);
                    let mut properties = json!({
                        "$pathname": path,
                        "$current_url": format!("https://example.com{path}"),
                        "$host": "example.com",
                        "$browser": browser,
                        "$os": os,
                        "$device_type": device_type,
                        "$lib": "web",
                        "plan": plan,
                    });
                    let props = properties.as_object_mut().expect("object");
                    if let Some(country) = country {
                        props.insert("$geoip_country_code".into(), json!(country));
                    }
                    if let Some(session_id) = &session_id {
                        props.insert("$session_id".into(), json!(session_id));
                    }
                    if view == 0 {
                        props.insert(
                            "$referring_domain".into(),
                            json!(if direct { "$direct" } else { referrer }),
                        );
                        if tagged {
                            props.insert("utm_source".into(), json!(utm.0));
                            props.insert("utm_medium".into(), json!(utm.1));
                            props.insert("utm_campaign".into(), json!(utm.2));
                        }
                    } else {
                        // Multi-page app: internal navigations refer to self.
                        props.insert("$referring_domain".into(), json!("example.com"));
                    }
                    events.push(event("$pageview", &current_id, at, properties));
                    at += Duration::seconds(rng.gen_range(5..600));
                    if view == 0 && login_session == Some(index) && current_id == anon {
                        let mut identify = json!({
                            "$anon_distinct_id": anon,
                            "$set": {
                                "email": format!("person{human}@example.com"),
                                "name": format!("Person {human}"),
                                "plan": plan,
                            },
                        });
                        if let Some(session_id) = &session_id {
                            identify
                                .as_object_mut()
                                .expect("object")
                                .insert("$session_id".into(), json!(session_id));
                        }
                        events.push(event("$identify", &user_id, at, identify));
                        current_id = user_id.clone();
                        at += Duration::seconds(rng.gen_range(5..60));
                    }
                    if rng.gen_bool(0.25) {
                        let mut click = json!({"$event_type": "click", "$pathname": path});
                        if let Some(session_id) = &session_id {
                            click
                                .as_object_mut()
                                .expect("object")
                                .insert("$session_id".into(), json!(session_id));
                        }
                        events.push(event("$autocapture", &current_id, at, click));
                        at += Duration::seconds(rng.gen_range(5..300));
                    }
                }
            }
        }
        if identifies {
            person_of.insert(user_id.clone(), user_id.clone());
            for _ in 0..rng.gen_range(0..=2) {
                let at = spec.start + Duration::seconds(rng.gen_range(0..span_seconds.max(1)));
                events.push(event(
                    "purchase",
                    &user_id,
                    at,
                    json!({"amount": rng.gen_range(5..500), "currency": "USD"}),
                ));
            }
        }
    }
    make_strictly_increasing(&mut events);
    Dataset { events, person_of }
}

pub fn make_strictly_increasing(events: &mut [CapturedEvent]) {
    events.sort_by_key(|event| event.timestamp);
    for index in 1..events.len() {
        if events[index].timestamp <= events[index - 1].timestamp {
            events[index].timestamp = events[index - 1].timestamp + Duration::microseconds(1);
        }
    }
}

/// A bootstrapped projections database, a directory lake, and an explorer.
pub struct Fixture {
    pub dir: tempfile::TempDir,
    pub source: Arc<DirectorySource>,
    pub persons: Arc<PersonStore>,
    pub explorer: Arc<Explorer>,
    pub projections: PathBuf,
    pub control: PathBuf,
    applied: u64,
    files: u64,
}

impl Fixture {
    pub fn new() -> Self {
        let dir = tempfile::tempdir().expect("tempdir");
        let control = dir.path().join("control.db");
        let projections = dir.path().join("projections.db");
        hoglet::storage_bootstrap::bootstrap_storage(&control, &projections)
            .expect("storage bootstrap");
        let connection = Connection::open(&projections).expect("projections open");
        hoglet::projections::initialize_schema(&connection).expect("projection schema");
        drop(connection);
        let source = Arc::new(DirectorySource::new(dir.path().join("events")));
        let persons = Arc::new(PersonStore::open(&projections).expect("person store"));
        let explorer = Arc::new(Explorer::new(source.clone(), persons.clone()).expect("explorer"));
        Self {
            dir,
            source,
            persons,
            explorer,
            projections,
            control,
            applied: 0,
            files: 0,
        }
    }

    /// Write `events` as Parquet, `files_per_day` files per UTC day.
    pub fn write_events(
        &mut self,
        project_id: &str,
        events: &[CapturedEvent],
        files_per_day: usize,
    ) {
        let mut by_day: BTreeMap<NaiveDate, Vec<CapturedEvent>> = BTreeMap::new();
        for event in events {
            by_day
                .entry(event.timestamp.date_naive())
                .or_default()
                .push(event.clone());
        }
        for (day, day_events) in by_day {
            let directory = self.source.partition_dir(project_id, day);
            std::fs::create_dir_all(&directory).expect("partition dir");
            let chunk = day_events.len().div_ceil(files_per_day.max(1)).max(1);
            for part in day_events.chunks(chunk) {
                self.files += 1;
                let path = directory.join(format!("part-{:06}.parquet", self.files));
                hoglet::lake::parquet::write_file(part, &path).expect("parquet write");
            }
        }
    }

    /// Apply events to the projections in order (WAL order = slice order).
    pub fn project<'a>(
        &mut self,
        project_id: &str,
        events: impl IntoIterator<Item = &'a CapturedEvent>,
    ) {
        let mut connection = Connection::open(&self.projections).expect("projections open");
        connection
            .execute_batch("PRAGMA journal_mode=WAL; PRAGMA synchronous=OFF;")
            .expect("pragmas");
        let transaction = connection.transaction().expect("transaction");
        for event in events {
            self.applied += 1;
            hoglet::projections::apply_captured_event(
                &transaction,
                project_id,
                event,
                WalCursor::new(1, self.applied),
            )
            .expect("projection apply");
        }
        transaction.commit().expect("commit");
    }

    /// Write and project, the common case.
    pub fn load(&mut self, project_id: &str, events: &[CapturedEvent]) {
        self.write_events(project_id, events, 2);
        self.project(project_id, events.iter());
    }
}

// ---------------------------------------------------------------------------
// Brute-force reference implementations.
// ---------------------------------------------------------------------------

pub fn micros(at: DateTime<Utc>) -> i64 {
    at.timestamp_micros()
}

pub fn text(event: &CapturedEvent, key: &str) -> Option<String> {
    match event.properties.get(key)? {
        Value::String(text) if !text.is_empty() => Some(text.clone()),
        Value::Number(number) => Some(number.to_string()),
        Value::Bool(flag) => Some(flag.to_string()),
        _ => None,
    }
}

#[derive(Debug, Clone)]
pub struct Session {
    pub period: usize,
    pub person: String,
    pub pageviews: u64,
    pub events: u64,
    pub autocaptures: u64,
    pub duration_us: i64,
    pub entry_page: Option<String>,
    pub exit_page: Option<String>,
    /// First pageview of the session.
    pub entry: CapturedEvent,
}

/// Tag every in-range, matching event with (period, person) and group
/// into pageview sessions, exactly per the documented definitions.
pub fn build_sessions(
    events: &[CapturedEvent],
    person: &dyn Fn(&str) -> String,
    periods: &[(i64, i64)],
    keep: &dyn Fn(&CapturedEvent) -> bool,
) -> (Vec<(usize, String, CapturedEvent)>, Vec<Session>) {
    let mut tagged = Vec::new();
    for event in events {
        let ts = micros(event.timestamp);
        let Some(period) = periods
            .iter()
            .position(|(from, to)| ts >= *from && ts < *to)
        else {
            continue;
        };
        if !keep(event) {
            continue;
        }
        tagged.push((period, person(&event.distinct_id), event.clone()));
    }
    tagged.sort_by_key(|(_, _, event)| (event.timestamp, event.uuid.to_string()));
    let mut groups: BTreeMap<(usize, String), Vec<(String, CapturedEvent)>> = BTreeMap::new();
    let mut last_seen: HashMap<(usize, String), (i64, u64)> = HashMap::new();
    for (period, person, event) in &tagged {
        let sid = match text(event, "$session_id") {
            Some(session) => format!("s{session}"),
            None => {
                let ts = micros(event.timestamp);
                let key = (*period, person.clone());
                let counter = match last_seen.get(&key) {
                    Some((previous, counter)) if ts - previous <= 30 * 60 * 1_000_000 => *counter,
                    Some((_, counter)) => counter + 1,
                    None => 1,
                };
                last_seen.insert(key, (ts, counter));
                format!("a{person}\u{1f}{counter}")
            }
        };
        groups
            .entry((*period, sid))
            .or_default()
            .push((person.clone(), event.clone()));
    }
    let mut out = Vec::new();
    for ((period, _), members) in groups {
        let pageviews: Vec<&(String, CapturedEvent)> = members
            .iter()
            .filter(|(_, event)| event.event == "$pageview")
            .collect();
        let Some(first) = pageviews.first() else {
            continue;
        };
        let last = pageviews.last().expect("non-empty");
        let min = members
            .iter()
            .map(|(_, e)| micros(e.timestamp))
            .min()
            .unwrap_or(0);
        let max = members
            .iter()
            .map(|(_, e)| micros(e.timestamp))
            .max()
            .unwrap_or(0);
        out.push(Session {
            period,
            person: first.0.clone(),
            pageviews: pageviews.len() as u64,
            events: members.len() as u64,
            autocaptures: members
                .iter()
                .filter(|(_, event)| event.event == "$autocapture")
                .count() as u64,
            duration_us: max - min,
            entry_page: text(&first.1, "$pathname"),
            exit_page: text(&last.1, "$pathname"),
            entry: first.1.clone(),
        });
    }
    (tagged, out)
}

impl Session {
    /// PostHog's bounce: one pageview, no autocapture, under 10 seconds.
    pub fn is_bounce(&self) -> bool {
        self.pageviews == 1 && self.autocaptures == 0 && self.duration_us < 10_000_000
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Default)]
pub struct PeriodMetrics {
    pub visitors: f64,
    pub pageviews: f64,
    pub sessions: f64,
    pub bounce_rate: f64,
    pub duration_s: f64,
}

pub fn period_metrics(
    tagged: &[(usize, String, CapturedEvent)],
    sessions: &[Session],
    period: usize,
) -> PeriodMetrics {
    let views: Vec<&(usize, String, CapturedEvent)> = tagged
        .iter()
        .filter(|(p, _, event)| *p == period && event.event == "$pageview")
        .collect();
    let visitors: HashSet<&String> = views.iter().map(|(_, person, _)| person).collect();
    let mine: Vec<&Session> = sessions.iter().filter(|s| s.period == period).collect();
    let bounces = mine
        .iter()
        .filter(|s| s.is_bounce())
        .count();
    let count = mine.len() as f64;
    PeriodMetrics {
        visitors: visitors.len() as f64,
        pageviews: views.len() as f64,
        sessions: count,
        bounce_rate: if count > 0.0 {
            100.0 * bounces as f64 / count
        } else {
            0.0
        },
        duration_s: if count > 0.0 {
            mine.iter().map(|s| s.duration_us as f64).sum::<f64>() / count / 1e6
        } else {
            0.0
        },
    }
}

pub fn approx(a: f64, b: f64) -> bool {
    (a - b).abs() <= 1e-6 * (1.0 + a.abs().max(b.abs()))
}

//! Shared harness for the claim 2 evidence: drive a real `hoglet` process
//! (built with the `fault-injection` feature), crash it at a named point,
//! restart it on the same data directory, and reconcile what the clients were
//! told (HTTP 200) against what is actually stored.
#![allow(dead_code)]

use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};
use std::net::{TcpListener, TcpStream};
use std::os::unix::process::ExitStatusExt;
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use rand::rngs::StdRng;
use rand::{Rng, SeedableRng};
use serde_json::{Value, json};
use uuid::Uuid;

pub const TOKEN: &str = "phc_claim2";
pub const EVENT: &str = "claim2_event";
pub const VICTIM_EVENT: &str = "claim2_victim_event";

/// Iterations per kill point; raise for nightly or one-off high-count runs.
pub fn seeds() -> u64 {
    std::env::var("HOGLET_FAULT_SEEDS")
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(2)
}

/// Ports are handed out from a per-process range and probed, so two servers
/// of one test run never share one and a stranger's listener is skipped.
pub fn free_port() -> u16 {
    static NEXT: AtomicU64 = AtomicU64::new(0);
    let base = 20_000 + (u64::from(std::process::id()) * 53) % 30_000;
    loop {
        let offset = NEXT.fetch_add(1, Ordering::SeqCst);
        let port = (base + offset) % 40_000 + 20_000;
        if TcpListener::bind(("127.0.0.1", port as u16)).is_ok() {
            return port as u16;
        }
    }
}

/// Print a result line, and append it to `HOGLET_MATRIX_OUT` when set.
pub fn log_line(line: &str) {
    use std::io::Write;
    println!("{line}");
    if let Ok(path) = std::env::var("HOGLET_MATRIX_OUT")
        && let Ok(mut file) = std::fs::OpenOptions::new().create(true).append(true).open(path)
    {
        let _ = writeln!(file, "{line}");
    }
}

// ---------------------------------------------------------------- process

pub struct Server {
    pub child: Child,
    pub port: u16,
    stderr_path: PathBuf,
}

impl Server {
    /// Spawn on `data_dir`; `env` arms faults. Retries on a port race.
    pub fn spawn(data_dir: &Path, env: &[(&str, String)]) -> Server {
        for attempt in 0..8 {
            let port = free_port();
            let stderr_path = data_dir.join(format!("server-{port}-{attempt}.log"));
            let stderr = std::fs::File::create(&stderr_path).expect("server log");
            let mut command = Command::new(env!("CARGO_BIN_EXE_hoglet"));
            command
                .env("HOGLET_DATA", data_dir)
                .env("HOGLET_ADDR", format!("127.0.0.1:{port}"))
                .env("HOGLET_MAX_EVENTS_PER_SEC", "1000000")
                .env("RUST_LOG", "hoglet=warn")
                .stdout(Stdio::from(stderr.try_clone().expect("clone log handle")))
                .stderr(Stdio::from(stderr));
            for (name, value) in env {
                command.env(name, value);
            }
            let child = command.spawn().expect("spawn hoglet");
            let mut server = Server {
                child,
                port,
                stderr_path,
            };
            match server.wait_until_up(Duration::from_secs(60)) {
                Up::Yes => return server,
                Up::Exited if server.log().contains("in use") => continue,
                Up::Exited => panic!(
                    "hoglet exited during startup ({:?}):\n{}",
                    server.child.try_wait(),
                    server.log()
                ),
                Up::Timeout => {
                    let _ = server.child.kill();
                    panic!("hoglet did not start in time:\n{}", server.log());
                }
            }
        }
        panic!("no free port after 8 attempts");
    }

    /// Spawn expecting the process to refuse to start; returns its log.
    pub fn spawn_expecting_failure(data_dir: &Path) -> String {
        let port = free_port();
        let stderr_path = data_dir.join(format!("server-fail-{port}.log"));
        let stderr = std::fs::File::create(&stderr_path).expect("server log");
        let mut child = Command::new(env!("CARGO_BIN_EXE_hoglet"))
            .env("HOGLET_DATA", data_dir)
            .env("HOGLET_ADDR", format!("127.0.0.1:{port}"))
            .stdout(Stdio::from(stderr.try_clone().expect("clone log handle")))
            .stderr(Stdio::from(stderr))
            .spawn()
            .expect("spawn hoglet");
        let deadline = Instant::now() + Duration::from_secs(60);
        loop {
            if let Some(status) = child.try_wait().expect("poll child") {
                assert!(!status.success(), "server started on a corrupt WAL");
                return std::fs::read_to_string(&stderr_path).unwrap_or_default();
            }
            if TcpStream::connect(("127.0.0.1", port)).is_ok() {
                let _ = child.kill();
                let _ = child.wait();
                panic!("server accepted connections on a corrupt WAL");
            }
            assert!(Instant::now() < deadline, "server neither started nor failed");
            std::thread::sleep(Duration::from_millis(20));
        }
    }

    pub fn log(&self) -> String {
        std::fs::read_to_string(&self.stderr_path).unwrap_or_default()
    }

    fn wait_until_up(&mut self, within: Duration) -> Up {
        let deadline = Instant::now() + within;
        while Instant::now() < deadline {
            if self.child.try_wait().expect("poll child").is_some() {
                return Up::Exited;
            }
            // A bare TCP connect can "succeed" against nothing at all (TCP
            // self-connect on an ephemeral-range port); only HTTP proves it.
            if http("GET", self.port, "/health", None, None).0 == Outcome::Acked {
                return Up::Yes;
            }
            std::thread::sleep(Duration::from_millis(20));
        }
        Up::Timeout
    }

    /// Did the process die from its own injected SIGKILL?
    pub fn killed_by_fault(&mut self) -> Option<String> {
        let status = self.child.try_wait().ok().flatten()?;
        (status.signal() == Some(9))
            .then(|| self.log())
            .filter(|log| log.contains("fault injection: aborting at"))
    }

    pub fn wait_for_death(&mut self, within: Duration) -> bool {
        let deadline = Instant::now() + within;
        while Instant::now() < deadline {
            if self.child.try_wait().expect("poll child").is_some() {
                return true;
            }
            std::thread::sleep(Duration::from_millis(10));
        }
        false
    }

    pub fn sigkill(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }

    /// SIGTERM: graceful shutdown (drain, publish the WAL).
    pub fn stop_gracefully(&mut self) {
        let _ = Command::new("kill")
            .arg("-TERM")
            .arg(self.child.id().to_string())
            .status();
        if !self.wait_for_death(Duration::from_secs(60)) {
            self.sigkill();
            panic!("graceful shutdown timed out:\n{}", self.log());
        }
    }
}

impl Drop for Server {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

enum Up {
    Yes,
    Exited,
    Timeout,
}

// ------------------------------------------------------------------- HTTP

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Outcome {
    /// 2xx: the client was told the events are durable.
    Acked,
    /// 5xx: retryable by SDKs.
    Retryable(u16),
    /// 4xx: SDKs never retry; a test that provokes one is wrong.
    Rejected(u16),
    /// Connection refused / reset / timed out.
    Unknown,
}

fn agent() -> ureq::Agent {
    ureq::AgentBuilder::new()
        .timeout_connect(Duration::from_secs(5))
        .timeout(Duration::from_secs(120))
        .build()
}

pub fn http(
    method: &str,
    port: u16,
    path: &str,
    body: Option<&Value>,
    cookie: Option<&str>,
) -> (Outcome, Value) {
    let url = format!("http://127.0.0.1:{port}{path}");
    let mut request = agent().request(method, &url);
    if let Some(cookie) = cookie {
        request = request.set("Cookie", cookie);
    }
    let result = match body {
        Some(body) => request.send_json(body.clone()),
        None => request.call(),
    };
    match result {
        Ok(response) => {
            let json = response
                .into_string()
                .ok()
                .and_then(|text| serde_json::from_str(&text).ok())
                .unwrap_or(Value::Null);
            (Outcome::Acked, json)
        }
        Err(ureq::Error::Status(code, response)) => {
            let json = response
                .into_string()
                .ok()
                .and_then(|text| serde_json::from_str(&text).ok())
                .unwrap_or(Value::Null);
            if code >= 500 {
                (Outcome::Retryable(code), json)
            } else {
                (Outcome::Rejected(code), json)
            }
        }
        Err(ureq::Error::Transport(_)) => (Outcome::Unknown, Value::Null),
    }
}

pub struct Project {
    pub id: String,
    pub cookie: String,
}

/// First-run setup through the real HTTP API; adopts `TOKEN` as the project's
/// capture token.
pub fn setup(port: u16) -> Project {
    let url = format!("http://127.0.0.1:{port}/api/auth/setup");
    let response = agent()
        .post(&url)
        .send_json(json!({
            "email": "owner@example.com",
            "password": "correct horse battery staple",
            "organization_name": "Claim 2",
            "project_name": "Durability",
            "existing_project_token": TOKEN
        }))
        .unwrap_or_else(|error| panic!("setup failed: {error}"));
    let cookie = response
        .header("set-cookie")
        .and_then(|value| value.split(';').next())
        .expect("session cookie")
        .to_owned();
    let body: Value = serde_json::from_str(&response.into_string().expect("body")).expect("json");
    let id = body["organizations"][0]["projects"][0]["id"]
        .as_str()
        .expect("project id")
        .to_owned();
    Project { id, cookie }
}

// ----------------------------------------------------------------- ledger

#[derive(Debug, Clone)]
pub struct Sent {
    pub event: String,
    pub distinct_id: String,
    pub micros: i64,
}

/// What the clients sent and what the server promised.
#[derive(Default)]
pub struct Ledger {
    pub sent: Mutex<HashMap<Uuid, Sent>>,
    pub acked: Mutex<HashSet<Uuid>>,
    pub retryable: AtomicU64,
    /// Set once any request was answered 5xx.
    pub failure_seen: AtomicBool,
    /// Requests that STARTED after a 5xx was already observed yet were
    /// answered 2xx. With a poisoned WAL this must stay zero.
    pub acks_after_failure: AtomicU64,
    /// Every distinct status code a 5xx carried.
    pub failure_codes: Mutex<BTreeSet<u16>>,
}

impl Ledger {
    pub fn acked_count(&self) -> usize {
        self.acked.lock().unwrap().len()
    }
}

/// Timestamps are unique per event so the feed's keyset paging is exact.
static CLOCK: AtomicU64 = AtomicU64::new(0);

pub struct EventPlan {
    pub uuid: Uuid,
    pub event: &'static str,
    pub distinct_id: String,
    pub timestamp: chrono::DateTime<chrono::Utc>,
}

pub fn plan_event(
    event: &'static str,
    distinct_id: String,
    days_ago: i64,
) -> EventPlan {
    let day = (chrono::Utc::now() - chrono::Duration::days(days_ago)).date_naive();
    let midnight = day.and_hms_opt(1, 0, 0).expect("time").and_utc();
    let tick = CLOCK.fetch_add(1, Ordering::SeqCst) as i64;
    EventPlan {
        uuid: Uuid::now_v7(),
        event,
        distinct_id,
        // Unique microsecond offsets, at most 11 hours into the day.
        timestamp: midnight + chrono::Duration::microseconds(1 + tick % 40_000_000_000),
    }
}

/// POST one batch; every event is recorded as sent first, acked only on 200.
pub fn post_batch(port: u16, ledger: &Ledger, plans: &[EventPlan]) -> Outcome {
    let failed_before_send = ledger.failure_seen.load(Ordering::SeqCst);
    {
        let mut sent = ledger.sent.lock().unwrap();
        for plan in plans {
            sent.insert(
                plan.uuid,
                Sent {
                    event: plan.event.to_owned(),
                    distinct_id: plan.distinct_id.clone(),
                    micros: plan.timestamp.timestamp_micros(),
                },
            );
        }
    }
    let batch: Vec<Value> = plans
        .iter()
        .map(|plan| {
            json!({
                "event": plan.event,
                "distinct_id": plan.distinct_id,
                "uuid": plan.uuid.to_string(),
                "timestamp": plan.timestamp.to_rfc3339_opts(chrono::SecondsFormat::Micros, true),
                "properties": {"claim2_payload": plan.uuid.simple().to_string()}
            })
        })
        .collect();
    let (outcome, _) = http(
        "POST",
        port,
        "/batch/",
        Some(&json!({"api_key": TOKEN, "batch": batch})),
        None,
    );
    match outcome {
        Outcome::Acked => {
            if failed_before_send {
                ledger.acks_after_failure.fetch_add(1, Ordering::SeqCst);
            }
            let mut acked = ledger.acked.lock().unwrap();
            acked.extend(plans.iter().map(|plan| plan.uuid));
        }
        Outcome::Retryable(code) => {
            ledger.retryable.fetch_add(1, Ordering::Relaxed);
            ledger.failure_seen.store(true, Ordering::SeqCst);
            ledger.failure_codes.lock().unwrap().insert(code);
        }
        _ => {}
    }
    outcome
}

/// Writers hammering the server until `stop` is set or the server stops
/// answering. Returns the join handles.
pub struct Writers {
    stop: Arc<AtomicBool>,
    handles: Vec<std::thread::JoinHandle<()>>,
}

impl Writers {
    pub fn start(
        port: u16,
        ledger: &Arc<Ledger>,
        seed: u64,
        count: usize,
        max_batch: usize,
        pace_ms: u64,
        id_prefix: &str,
    ) -> Writers {
        let stop = Arc::new(AtomicBool::new(false));
        let handles = (0..count)
            .map(|writer| {
                let stop = stop.clone();
                let ledger = ledger.clone();
                let prefix = id_prefix.to_owned();
                std::thread::spawn(move || {
                    let mut rng = StdRng::seed_from_u64(seed.wrapping_mul(1_000).wrapping_add(writer as u64));
                    while !stop.load(Ordering::Relaxed) {
                        let size = rng.gen_range(1..=max_batch);
                        let plans: Vec<EventPlan> = (0..size)
                            .map(|_| {
                                // Mostly past days so partitions are compactable.
                                let days_ago = if rng.gen_bool(0.75) { rng.gen_range(2..=3) } else { 0 };
                                plan_event(
                                    EVENT,
                                    format!("{prefix}w{writer}-{}", rng.gen_range(0..16)),
                                    days_ago,
                                )
                            })
                            .collect();
                        match post_batch(port, &ledger, &plans) {
                            // A timeout under load must not retire the writer
                            // (the fault may then never be reached); a dead
                            // server just refuses quickly until `stop`.
                            Outcome::Unknown => {
                                std::thread::sleep(Duration::from_millis(20));
                            }
                            Outcome::Rejected(code) => panic!("capture answered {code}; the harness sent a bad batch"),
                            _ => {}
                        }
                        if pace_ms > 0 {
                            std::thread::sleep(Duration::from_millis(rng.gen_range(0..=pace_ms)));
                        }
                    }
                })
            })
            .collect();
        Writers { stop, handles }
    }

    pub fn stop(self) {
        self.stop.store(true, Ordering::Relaxed);
        for handle in self.handles {
            handle.join().expect("writer thread");
        }
    }

    pub fn finished(&self) -> bool {
        self.handles.iter().all(|handle| handle.is_finished())
    }
}

// ------------------------------------------------------------ polling

pub fn wait_until(what: &str, within: Duration, mut condition: impl FnMut() -> bool) {
    let deadline = Instant::now() + within;
    loop {
        if condition() {
            return;
        }
        assert!(Instant::now() < deadline, "timed out waiting for {what}");
        std::thread::sleep(Duration::from_millis(50));
    }
}

pub fn status_stored_events(port: u16, project: &Project) -> Option<u64> {
    let (outcome, body) = http(
        "GET",
        port,
        &format!("/api/projects/{}/status", project.id),
        None,
        Some(&project.cookie),
    );
    (outcome == Outcome::Acked).then(|| body["stored_events"].as_u64()).flatten()
}

// ------------------------------------------------------------- the lake

#[derive(Debug)]
pub struct CatalogView {
    pub live: Vec<(PathBuf, u64)>,
    pub known_paths: BTreeSet<PathBuf>,
    pub generation: u64,
    pub checkpoint: (u64, u64),
}

fn open_projections(data_dir: &Path) -> rusqlite::Connection {
    let connection = rusqlite::Connection::open_with_flags(
        data_dir.join("projections.db"),
        rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY,
    )
    .expect("projections.db");
    connection.busy_timeout(Duration::from_secs(10)).expect("busy");
    connection
}

pub fn catalog(data_dir: &Path) -> CatalogView {
    let connection = open_projections(data_dir);
    let root = std::fs::canonicalize(data_dir.join("events")).unwrap_or_else(|_| data_dir.join("events"));
    let mut live = Vec::new();
    let mut known = BTreeSet::new();
    let mut statement = connection
        .prepare("SELECT relative_path, rows, retired_generation IS NULL FROM lake_files")
        .expect("catalog query");
    let rows = statement
        .query_map([], |row| {
            Ok((row.get::<_, String>(0)?, row.get::<_, i64>(1)?, row.get::<_, bool>(2)?))
        })
        .expect("catalog rows");
    for row in rows {
        let (relative, rows, is_live) = row.expect("row");
        let path = root.join(relative);
        known.insert(path.clone());
        if is_live {
            live.push((path, rows as u64));
        }
    }
    let (generation, segment, offset): (i64, i64, i64) = connection
        .query_row(
            "SELECT generation, wal_segment, wal_offset FROM projection_state",
            [],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .expect("projection state");
    CatalogView {
        live,
        known_paths: known,
        generation: generation as u64,
        checkpoint: (segment as u64, offset as u64),
    }
}

/// Parquet and temporary files on disk under `events/`.
pub fn lake_files_on_disk(data_dir: &Path) -> BTreeSet<PathBuf> {
    let root = std::fs::canonicalize(data_dir.join("events")).unwrap_or_else(|_| data_dir.join("events"));
    let mut found = BTreeSet::new();
    let mut stack = vec![root];
    while let Some(dir) = stack.pop() {
        for entry in std::fs::read_dir(&dir).into_iter().flatten().flatten() {
            let path = entry.path();
            if path.is_dir() {
                stack.push(path);
            } else {
                found.insert(path);
            }
        }
    }
    found
}

#[derive(Debug, Clone)]
pub struct StoredRow {
    pub uuid: String,
    pub event: String,
    pub distinct_id: String,
    pub micros: i64,
    pub payload: Option<String>,
}

/// Every row of every live file, read straight from Parquet with DuckDB.
/// A running server may compact (and unlink) files between the catalog read
/// and the Parquet read; retry against a fresh catalog.
pub fn stored_rows(data_dir: &Path) -> Result<Vec<StoredRow>, String> {
    let mut last = String::new();
    for _ in 0..40 {
        match stored_rows_once(data_dir) {
            Ok(rows) => return Ok(rows),
            Err(error) => last = error,
        }
        std::thread::sleep(Duration::from_millis(100));
    }
    Err(last)
}

fn stored_rows_once(data_dir: &Path) -> Result<Vec<StoredRow>, String> {
    let view = catalog(data_dir);
    if view.live.is_empty() {
        return Ok(Vec::new());
    }
    let files = view
        .live
        .iter()
        .map(|(path, _)| format!("'{}'", path.display()))
        .collect::<Vec<_>>()
        .join(", ");
    let duck = duckdb::Connection::open_in_memory().map_err(|e| e.to_string())?;
    let mut statement = duck
        .prepare(&format!(
            "SELECT uuid, event, distinct_id, epoch_us(timestamp)::BIGINT,
                    json_extract_string(properties, '$.claim2_payload')
             FROM read_parquet([{files}], union_by_name = true)"
        ))
        .map_err(|e| e.to_string())?;
    let rows = statement
        .query_map([], |row| {
            Ok(StoredRow {
                uuid: row.get(0)?,
                event: row.get(1)?,
                distinct_id: row.get(2)?,
                micros: row.get(3)?,
                payload: row.get(4)?,
            })
        })
        .map_err(|e| e.to_string())?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|e| e.to_string())?;
    Ok(rows)
}

pub fn parquet_row_count(path: &Path) -> Result<u64, String> {
    let duck = duckdb::Connection::open_in_memory().map_err(|e| e.to_string())?;
    duck.query_row(
        &format!("SELECT count(*) FROM read_parquet('{}')", path.display()),
        [],
        |row| row.get::<_, i64>(0),
    )
    .map(|count| count as u64)
    .map_err(|e| e.to_string())
}

/// Distinct ids with a person, and the person count.
pub fn identity_view(data_dir: &Path) -> (BTreeSet<String>, u64, u64) {
    let connection = open_projections(data_dir);
    let mut statement = connection
        .prepare("SELECT distinct_id FROM distinct_ids")
        .expect("distinct ids");
    let ids: BTreeSet<String> = statement
        .query_map([], |row| row.get(0))
        .expect("rows")
        .collect::<Result<_, _>>()
        .expect("ids");
    let persons: i64 = connection
        .query_row("SELECT count(*) FROM persons", [], |row| row.get(0))
        .expect("persons");
    let orphan_persons: i64 = connection
        .query_row(
            "SELECT count(*) FROM persons p WHERE NOT EXISTS
               (SELECT 1 FROM distinct_ids d WHERE d.project_id = p.project_id AND d.person_id = p.id)",
            [],
            |row| row.get(0),
        )
        .expect("orphans");
    (ids, persons as u64, orphan_persons as u64)
}

// -------------------------------------------------------------- verdicts

#[derive(Debug, Default, Clone)]
pub struct Report {
    pub acked: usize,
    pub sent: usize,
    pub stored: usize,
    /// Durable but never acknowledged: allowed to exist, never required.
    pub unacked_but_stored: usize,
    pub lake_files: usize,
    pub aborted_at: String,
}

/// Reconcile the clients' ledger with the stored events. `erased` is the set
/// of distinct ids whose events must be gone.
pub fn reconcile(
    data_dir: &Path,
    ledger: &Ledger,
    erased: &BTreeSet<String>,
) -> Result<Report, String> {
    let rows = stored_rows(data_dir)?;
    let sent = ledger.sent.lock().unwrap();
    let acked = ledger.acked.lock().unwrap();
    let mut seen: HashMap<&str, &StoredRow> = HashMap::new();
    for row in &rows {
        if seen.insert(row.uuid.as_str(), row).is_some() {
            return Err(format!("event {} is stored twice", row.uuid));
        }
        let uuid: Uuid = row.uuid.parse().map_err(|_| format!("stored garbage uuid {}", row.uuid))?;
        let Some(expected) = sent.get(&uuid) else {
            return Err(format!("event {uuid} is stored but was never sent (phantom data)"));
        };
        if expected.event != row.event
            || expected.distinct_id != row.distinct_id
            || expected.micros != row.micros
            || row.payload.as_deref() != Some(uuid.simple().to_string().as_str())
        {
            return Err(format!("event {uuid} is stored altered: sent {expected:?}, stored {row:?}"));
        }
        if erased.contains(&row.distinct_id) {
            return Err(format!("erased person's event {uuid} (distinct id {}) survived", row.distinct_id));
        }
    }
    let lost: Vec<&Uuid> = acked
        .iter()
        .filter(|uuid| {
            let id = &sent[*uuid].distinct_id;
            !erased.contains(id) && !seen.contains_key(uuid.to_string().as_str())
        })
        .collect();
    if !lost.is_empty() {
        return Err(format!(
            "{} of {} acknowledged events were lost, e.g. {}",
            lost.len(),
            acked.len(),
            lost[0]
        ));
    }
    let unacked_but_stored = rows
        .iter()
        .filter(|row| row.uuid.parse::<Uuid>().is_ok_and(|uuid| !acked.contains(&uuid)))
        .count();
    Ok(Report {
        acked: acked.len(),
        sent: sent.len(),
        stored: rows.len(),
        unacked_but_stored,
        lake_files: catalog(data_dir).live.len(),
        aborted_at: String::new(),
    })
}

/// No orphan files, no missing files, row counts match, identity matches the
/// events. Polled: a live server may still be sweeping retired files.
pub fn check_consistent(data_dir: &Path, erased: &BTreeSet<String>) -> Result<(), String> {
    let deadline = Instant::now() + Duration::from_secs(20);
    loop {
        match consistency_problem(data_dir, erased) {
            None => return Ok(()),
            Some(problem) if Instant::now() >= deadline => return Err(problem),
            Some(_) => std::thread::sleep(Duration::from_millis(100)),
        }
    }
}

fn consistency_problem(data_dir: &Path, erased: &BTreeSet<String>) -> Option<String> {
    let view = catalog(data_dir);
    let on_disk = lake_files_on_disk(data_dir);
    if let Some(orphan) = on_disk.difference(&view.known_paths).next() {
        return Some(format!("orphan file left on disk: {}", orphan.display()));
    }
    for (path, rows) in &view.live {
        if !path.is_file() {
            return Some(format!("catalogued file is missing: {}", path.display()));
        }
        match parquet_row_count(path) {
            Ok(actual) if actual == *rows => {}
            Ok(actual) => {
                return Some(format!("catalog says {rows} rows, parquet has {actual}: {}", path.display()));
            }
            Err(error) => return Some(format!("unreadable parquet {}: {error}", path.display())),
        }
    }
    let rows = match stored_rows(data_dir) {
        Ok(rows) => rows,
        Err(error) => return Some(format!("cannot read lake: {error}")),
    };
    let (ids, persons, orphan_persons) = identity_view(data_dir);
    let event_ids: BTreeSet<String> = rows.iter().map(|row| row.distinct_id.clone()).collect();
    if let Some(missing) = event_ids.difference(&ids).next() {
        return Some(format!("stored events for {missing} have no person (identity and lake diverged)"));
    }
    if let Some(extra) = ids.iter().find(|id| erased.contains(*id)) {
        return Some(format!("erased distinct id {extra} still has a person"));
    }
    if orphan_persons != 0 {
        return Some(format!("{orphan_persons} persons have no distinct id"));
    }
    if persons > ids.len() as u64 {
        return Some(format!("{persons} persons for {} distinct ids", ids.len()));
    }
    None
}

/// All event uuids visible through `GET /events`, paged to exhaustion.
pub fn feed_uuids(port: u16, project: &Project, event: &str) -> BTreeSet<String> {
    let mut found = BTreeSet::new();
    let mut before: Option<String> = None;
    for _ in 0..10_000 {
        let mut path = format!("/api/projects/{}/events?event={event}&limit=200", project.id);
        if let Some(before) = &before {
            path.push_str(&format!("&before={}", before.replace('+', "%2B").replace(':', "%3A")));
        }
        let (outcome, body) = http("GET", port, &path, None, Some(&project.cookie));
        assert_eq!(outcome, Outcome::Acked, "events feed failed: {body}");
        for row in body["events"].as_array().expect("events array") {
            found.insert(row["uuid"].as_str().expect("uuid").to_owned());
        }
        match body["next_before"].as_str() {
            Some(next) => before = Some(next.to_owned()),
            None => break,
        }
    }
    found
}

/// Wait until every acknowledged (non-erased) event is queryable.
pub fn wait_until_queryable(port: u16, project: &Project, ledger: &Ledger, erased: &BTreeSet<String>) {
    let want: BTreeSet<String> = {
        let sent = ledger.sent.lock().unwrap();
        ledger
            .acked
            .lock()
            .unwrap()
            .iter()
            .filter(|uuid| !erased.contains(&sent[*uuid].distinct_id))
            .map(Uuid::to_string)
            .collect()
    };
    wait_until("acknowledged events to be queryable through the API", Duration::from_secs(60), || {
        feed_uuids(port, project, EVENT).is_superset(&want)
    });
}

pub fn count_by_event(rows: &[StoredRow]) -> BTreeMap<String, usize> {
    let mut counts = BTreeMap::new();
    for row in rows {
        *counts.entry(row.event.clone()).or_insert(0) += 1;
    }
    counts
}

// posthog-js `latest`, unmodified, in headless Chromium against a real
// Hoglet (claims.md claim 1). The page is served from a local origin
// (`localhost`) and talks cross-origin to `127.0.0.1`, so CORS is exercised.
// Requests go through the counting proxy so retries, beacons and statuses
// are observed at the wire, not inferred from the browser.

import { randomUUID } from "node:crypto";
import { readFileSync } from "node:fs";
import http from "node:http";
import { chromium } from "playwright";

import {
  FLAG_PAYLOAD_ON,
  Hoglet,
  Proxy,
  assertDauIsOne,
  createFlags,
  decodeBody,
  eventsIn,
  expectedVariant,
  isCapturePath,
  listEvents,
  poll,
  repeatedRequests,
  runId,
  setupWorkspace,
  waitForEvents,
  waitForSinglePerson,
} from "./lib/harness.mjs";
import { Report, eq, fail, ok } from "./lib/report.mjs";

const pkg = (name) => JSON.parse(readFileSync(new URL(`./node_modules/${name}/package.json`, import.meta.url))).version;
const SDK_VERSION = pkg("posthog-js");
const report = new Report("browser");
report.meta.sdk = { "posthog-js": SDK_VERSION, playwright: pkg("playwright") };
report.header(`browser suite — posthog-js ${SDK_VERSION} (playwright ${pkg("playwright")})`);

const hoglet = new Hoglet({ label: "browser" });
await hoglet.start();
const proxy = await new Proxy(hoglet).listen();

const ws = await report.step("setup: POST /api/auth/setup returns session cookie, project id and token", () =>
  setupWorkspace(hoglet.url, "browser")
);
if (!ws) process.exit(report.finish());
const { api, projectId, token } = ws;
await createFlags(report, api, projectId);

const run = runId();
const user = `browser-${run}@contract.test`;

// ── the host page ────────────────────────────────────────────────────────

const SDK_JS = readFileSync(new URL("./node_modules/posthog-js/dist/array.js", import.meta.url));
const page1 = `<!doctype html><html><head><title>contract</title><link rel="icon" href="data:,"></head>
<body><h1>contract</h1><button id="cta">Buy</button>
<script src="/posthog.js"></script>
<script>
  window.__flagCalls = [];
  posthog.init(${JSON.stringify(token)}, {
    api_host: ${JSON.stringify(proxy.url)},
    // posthog-js drops events from navigator.webdriver browsers (bot
    // filter); this is the SDK's own switch for automation, not a Hoglet option.
    opt_out_useragent_filter: true,
    loaded: () => { window.__loaded = true; },
  });
  posthog.register({ ct_run: ${JSON.stringify(run)} });
  posthog.onFeatureFlags((flags, variants) => window.__flagCalls.push({ flags, variants }));
</script></body></html>`;
const page2 = `<!doctype html><html><head><title>next</title><link rel="icon" href="data:,"></head><body>next</body></html>`;

const site = http.createServer((req, res) => {
  const path = new URL(req.url, "http://x").pathname;
  if (path === "/") return res.writeHead(200, { "content-type": "text/html" }).end(page1);
  if (path === "/next") return res.writeHead(200, { "content-type": "text/html" }).end(page2);
  if (path === "/posthog.js") return res.writeHead(200, { "content-type": "text/javascript" }).end(SDK_JS);
  res.writeHead(404).end();
});
const sitePort = await new Promise((r) => site.listen(0, "127.0.0.1", () => r(site.address().port)));
const origin = `http://localhost:${sitePort}`;

const browser = await chromium.launch({ headless: true });
// Chrome's Local Network Access gate: real sites target a routable host;
// granting it here is rig plumbing, not a weakened claim.
const context = await browser.newContext({ permissions: ["local-network-access"] }).catch(() => browser.newContext());
const page = await context.newPage();
const consoleErrors = [];
page.on("console", (m) => {
  if (m.type() === "error") consoleErrors.push(m.text());
});
page.on("pageerror", (e) => consoleErrors.push(`pageerror: ${e.message}`));

const wireEvents = (records) => records.filter((r) => isCapturePath(r.path)).flatMap((r) => eventsIn(decodeBody(r.body)).map((e) => ({ e, r })));
const flagCalls = () => page.evaluate(() => window.__flagCalls.length);

try {
  await report.step("init: posthog-js loads from the page and init's loaded callback fires", async () => {
    await page.goto(`${origin}/`);
    await page.waitForFunction(() => window.__loaded === true, null, { timeout: 10_000 });
  });

  await report.step("init: remote config /array/{token}/config fetched with 200 and parseable JSON", async () => {
    const cfg = await poll(() => {
      const r = proxy.log.find((r) => r.path.startsWith(`/array/${token}/config`) && r.status !== null && r.response);
      if (!r) fail("no config request completed", proxy.log.map((r) => `${r.method} ${r.path}`), `GET /array/${token}/config`);
      return r;
    }, { timeoutMs: 5_000 });
    eq(cfg.status, 200, "config status");
    const text = cfg.response.toString("utf8");
    const parsed = cfg.path.endsWith(".js") ? text.length > 0 : JSON.parse(text);
    ok(parsed, "config body", text.slice(0, 200), "JSON object");
  });

  const anonId = await page.evaluate(() => posthog.get_distinct_id());

  await report.step("capture: autocaptured $pageview reaches a capture endpoint and is acknowledged 200", () =>
    poll(() => {
      const hit = wireEvents(proxy.log).find(({ e }) => e.event === "$pageview");
      if (!hit) fail("no $pageview on the wire", wireEvents(proxy.log).map(({ e }) => e.event), "$pageview");
      eq(hit.r.status, 200, "capture status");
    }, { timeoutMs: 10_000 })
  );

  await report.step("flags: onFeatureFlags fires and flags resolve for the anonymous user", async () => {
    await page.waitForFunction(() => window.__flagCalls.length > 0, null, { timeout: 10_000 });
    const got = await page.evaluate(() => ({
      on: posthog.isFeatureEnabled("ct-bool-on"),
      off: posthog.isFeatureEnabled("ct-bool-off"),
      inactive: !!posthog.isFeatureEnabled("ct-inactive"),
      mv: posthog.getFeatureFlag("ct-multivariate"),
      payload: posthog.getFeatureFlagPayload("ct-bool-on"),
    }));
    eq(got, { on: true, off: false, inactive: false, mv: expectedVariant("ct-multivariate", anonId), payload: FLAG_PAYLOAD_ON }, "flags");
  });

  const callsBeforeIdentify = await flagCalls();
  await page.evaluate((u) => posthog.identify(u, { plan: "enterprise", email: u }), user);

  await report.step("identify: flags reload for the identified user (variant + person-property flag)", async () => {
    await page.waitForFunction((n) => window.__flagCalls.length > n, callsBeforeIdentify, { timeout: 10_000 });
    const got = await page.evaluate(() => ({
      id: posthog.get_distinct_id(),
      mv: posthog.getFeatureFlag("ct-multivariate"),
      plan: posthog.isFeatureEnabled("ct-person-plan"),
    }));
    eq(got, { id: user, mv: expectedVariant("ct-multivariate", user), plan: true }, "flags after identify");
  });

  await report.step("identify: $identify carries $anon_distinct_id and is acknowledged 200", () =>
    poll(() => {
      const hit = wireEvents(proxy.log).find(({ e }) => e.event === "$identify");
      if (!hit) fail("no $identify on the wire", wireEvents(proxy.log).map(({ e }) => e.event), "$identify");
      eq({ anon: hit.e.properties?.$anon_distinct_id, status: hit.r.status }, { anon: anonId, status: 200 }, "$identify");
    }, { timeoutMs: 10_000 })
  );

  await report.step("capture: send_instantly event leaves within 1.5s and is acknowledged 200", async () => {
    const t0 = Date.now();
    await page.evaluate(() => posthog.capture("ct_instant", { kind: "instant" }, { send_instantly: true }));
    await poll(() => {
      const hit = wireEvents(proxy.log).find(({ e }) => e.event === "ct_instant");
      if (!hit) fail("ct_instant not on the wire", null, "ct_instant");
      eq(hit.r.status, 200, "capture status");
      ok(hit.r.t - t0 <= 1500, "sent instantly", `${hit.r.t - t0}ms`, "<= 1500ms");
    }, { timeoutMs: 3_000, intervalMs: 50 });
  });

  // posthog-js flushes its queue with navigator.sendBeacon on pagehide. A
  // beacon is a no-cors request (no preflight, response unreadable), so it
  // must be accepted as sent: CORS-simple content type, base64 body.
  // spec: `beacon=1` in the query → 204.
  await report.step("beacon: queued event is flushed with sendBeacon on unload and acknowledged 2xx (204 if beacon=1)", async () => {
    const mark = proxy.mark();
    await page.evaluate(() => posthog.capture("ct_beacon", { kind: "beacon" }));
    await page.goto(`${origin}/next`);
    await poll(() => {
      const hit = wireEvents(proxy.since(mark)).find(({ e }) => e.event === "ct_beacon");
      if (!hit) fail("ct_beacon not on the wire", proxy.since(mark).map((r) => `${r.method} ${r.path}`), "ct_beacon");
      const r = hit.r;
      const observed = {
        transport: r.headers["sec-fetch-mode"] === "no-cors" ? "sendBeacon" : `other (sec-fetch-mode=${r.headers["sec-fetch-mode"]})`,
        status: r.status,
      };
      const expected = { transport: "sendBeacon", status: r.query.beacon === "1" ? 204 : r.status >= 200 && r.status < 300 ? r.status : "2xx" };
      eq(observed, expected, `beacon request ${r.path}?${new URLSearchParams(r.query)}`);
    }, { timeoutMs: 5_000 });
  });

  // Older posthog-js marked beacons with `?beacon=1` (spec: answer 204).
  // Latest no longer does, so send one the way it used to, from the page.
  await report.step("beacon: legacy sendBeacon to /e/?beacon=1 (form data=base64) answers 204", async () => {
    const mark = proxy.mark();
    const queued = await page.evaluate(
      ([host, tok, id]) => {
        const event = { event: "ct_legacy_beacon", properties: { distinct_id: id, token: tok, kind: "legacy-beacon" } };
        const body = "data=" + encodeURIComponent(btoa(JSON.stringify(event)));
        return navigator.sendBeacon(`${host}/e/?compression=base64&beacon=1`, new Blob([body], { type: "application/x-www-form-urlencoded" }));
      },
      [proxy.url, token, user]
    );
    ok(queued, "navigator.sendBeacon queued the request", queued, true);
    await poll(() => {
      const hit = proxy.since(mark).find((r) => r.query.beacon === "1");
      if (!hit || hit.status === null) fail("beacon=1 request not answered yet", null, "a response");
      eq(hit.status, 204, "status");
    }, { timeoutMs: 5_000, intervalMs: 50 });
  });

  await report.step("wire: no capture/flags/config request answered 4xx/5xx", () => {
    const bad = proxy.log.filter((r) => r.method !== "OPTIONS" && !r.path.startsWith("/static/") && (typeof r.status !== "number" || r.status >= 400));
    eq(bad.map((r) => `${r.method} ${r.path} → ${r.status}`), [], "failed requests");
  });

  // posthog-js lazy-loads extension bundles from `${api_host}/static/` once
  // remote config arrives (surveys.js even when `surveys: false`). Against
  // PostHog these exist; a 404 without CORS headers is a console error.
  await report.step("wire: extension assets the SDK requests from /static/ load", () => {
    const bad = proxy.log.filter((r) => r.method !== "OPTIONS" && r.path.startsWith("/static/") && (typeof r.status !== "number" || r.status >= 400));
    eq(bad.map((r) => `${r.method} ${r.path} → ${r.status}`), [], "failed asset requests");
  });

  await report.step("wire: no request was retried (no repeated method+path+payload)", () =>
    eq(repeatedRequests(proxy.log), [], "repeated requests")
  );

  await report.step("console: no errors logged by the page or SDK", () => eq(consoleErrors, [], "console errors"));

  // ── stored outcomes ────────────────────────────────────────────────────

  const names = ["$pageview", "$identify", "ct_instant", "ct_beacon", "ct_legacy_beacon"];
  const stored = await report.step("stored: $pageview, $identify, ct_instant, ct_beacon and ct_legacy_beacon are listed by GET /events", () =>
    poll(async () => {
      const events = await listEvents(api, projectId);
      const have = names.filter((n) => events.some((e) => e.event === n));
      eq(have, names, "stored event names");
      return events;
    })
  );
  await report.step("stored: $pageview has the anonymous distinct_id and the page URL", () => {
    const pv = stored?.find((e) => e.event === "$pageview") ?? fail("no stored $pageview", null, "$pageview");
    eq({ distinct_id: pv.distinct_id, url: pv.properties?.$current_url, run: pv.properties?.ct_run }, { distinct_id: anonId, url: `${origin}/`, run }, "$pageview");
  });
  await report.step("stored: identify merged the anonymous and identified ids into ONE person", () =>
    waitForSinglePerson(api, projectId, [anonId, user])
  );
  await report.step("stored: TrendsQuery math=dau over all events counts 1 person", () => assertDauIsOne(api, projectId));

  // ── retry contract (last: it deliberately creates a retry) ─────────────

  await page.goto(`${origin}/`);
  await page.waitForFunction(() => window.__loaded === true, null, { timeout: 10_000 });
  const marker = randomUUID();
  const isMarked = (r) => isCapturePath(r.path) && eventsIn(decodeBody(r.body)).some((e) => e.properties?.marker === marker);
  proxy.inject(isMarked, { status: 503 });
  const mark = proxy.mark();
  const retried = await report.step("retry: 503 → posthog-js retries until acknowledged", async () => {
    await page.evaluate((m) => posthog.capture("ct_retry", { marker: m }, { send_instantly: true }), marker);
    return await poll(() => {
      const attempts = proxy.since(mark).filter(isMarked);
      if (!(attempts.length >= 2 && attempts.at(-1).status === 200)) fail("attempts", attempts.map((r) => r.status), "[503, 200]");
      return attempts;
    }, { timeoutMs: 20_000, intervalMs: 100 });
  });
  if (retried) {
    await report.step("retry: event retried after 503 is stored exactly once", async () => {
      const uuid = eventsIn(decodeBody(retried.at(-1).body)).find((e) => e.properties?.marker === marker)?.uuid;
      ok(uuid, "retried event has a uuid", uuid, "uuid");
      const events = await waitForEvents(api, projectId, [uuid]);
      eq(events.filter((e) => e.uuid === uuid).length, 1, "stored copies");
    });
  } else report.skip("retry: event retried after 503 is stored exactly once", "retry did not complete");
} finally {
  await browser.close();
  site.close();
  await proxy.close();
  await hoglet.stop();
}

const code = report.finish();
if (code !== 0) report.info(`hoglet log tail:\n${hoglet.logTail(15)}`);
hoglet.destroy();
process.exit(code);
